std::vector<ManualObjectDranEvent> loadManualObjectDranEventScheduleForTest(
    const std::string &path, std::size_t numRobots,
    std::size_t expectedEvents) {
  std::ifstream input(path);
  if (!input) {
    throw std::invalid_argument("failed to open ManualObjectDran event schedule");
  }
  std::string header;
  if (!std::getline(input, header)) {
    throw std::invalid_argument("event schedule is empty");
  }
  auto split = [](const std::string &line) {
    std::vector<std::string> fields;
    std::stringstream stream(line);
    std::string field;
    while (std::getline(stream, field, ',')) {
      fields.push_back(field);
    }
    return fields;
  };
  const std::vector<std::string> headerFields = split(header);
  if (headerFields.size() != 4u) {
    throw std::invalid_argument("event schedule header must have four columns");
  }
  std::map<std::string, std::size_t> columns;
  for (std::size_t i = 0; i < headerFields.size(); ++i) {
    if (columns.count(headerFields[i]) != 0u) {
      throw std::invalid_argument("event schedule header has duplicates");
    }
    columns[headerFields[i]] = i;
  }
  for (const char *required :
       {"event", "robot", "logical_time", "delay_events"}) {
    if (columns.count(required) == 0u) {
      throw std::invalid_argument("event schedule missing required header");
    }
  }
  std::vector<ManualObjectDranEvent> events;
  std::string line;
  double previousLogicalTime = -std::numeric_limits<double>::infinity();
  while (std::getline(input, line)) {
    if (line.empty()) {
      continue;
    }
    const std::vector<std::string> fields = split(line);
    if (fields.size() != headerFields.size()) {
      throw std::invalid_argument("event schedule row has wrong field count");
    }
    auto parseSize = [&](const std::string &name) {
      const std::string &text = fields[columns[name]];
      std::size_t consumed = 0;
      unsigned long long value = 0;
      try {
        value = std::stoull(text, &consumed);
      } catch (const std::exception &) {
        throw std::invalid_argument("event schedule has invalid integer");
      }
      if (consumed != text.size()) {
        throw std::invalid_argument("event schedule has invalid integer");
      }
      return static_cast<std::size_t>(value);
    };
    auto parseDouble = [&](const std::string &name) {
      const std::string &text = fields[columns[name]];
      std::size_t consumed = 0;
      double value = 0.0;
      try {
        value = std::stod(text, &consumed);
      } catch (const std::exception &) {
        throw std::invalid_argument("event schedule has invalid time");
      }
      if (consumed != text.size() || !std::isfinite(value)) {
        throw std::invalid_argument("event schedule has invalid time");
      }
      return value;
    };
    ManualObjectDranEvent event;
    event.event = parseSize("event");
    event.robot = parseSize("robot");
    event.logicalTime = parseDouble("logical_time");
    event.delayEvents = parseSize("delay_events");
    if (event.event != events.size()) {
      throw std::invalid_argument(
          "event schedule IDs must be contiguous and zero-based");
    }
    if (event.robot >= numRobots) {
      throw std::invalid_argument("event schedule robot is out of range");
    }
    if (event.logicalTime < 0.0 ||
        event.logicalTime < previousLogicalTime) {
      throw std::invalid_argument(
          "event schedule logical times must be nonnegative and monotone");
    }
    previousLogicalTime = event.logicalTime;
    events.push_back(event);
  }
  if (events.size() != expectedEvents) {
    throw std::invalid_argument(
        "event schedule must contain exactly maxIterations rows");
  }
  return events;
}

