struct AssociationPairValidationTrustStats {
  std::size_t activePairs{0};
  double trustSum{0.0};
  double minTrust{1.0};
  double riskSquaredSum{0.0};

  double meanTrust() const {
    return activePairs > 0u ? trustSum / static_cast<double>(activePairs)
                            : 1.0;
  }

  double riskRms() const {
    return activePairs > 0u
               ? std::sqrt(riskSquaredSum /
                           static_cast<double>(activePairs))
               : 0.0;
  }
};

