struct SharedEndpointStateMessage {
  std::size_t sender{0};
  std::size_t receiver{0};
  std::size_t object{0};
  std::size_t endpointSequence{0};
  std::size_t dueEvent{0};
  Matrix poseBlock;
};

struct SharedEndpointStateQueueStats {
  std::size_t queued{0};
  std::size_t delivered{0};
  std::size_t stale{0};
  std::size_t payloadBytes{0};
};

class SharedEndpointStateQueue {
 public:
  void enqueue(SharedEndpointStateMessage message) {
    messages_.push_back(std::move(message));
  }

  SharedEndpointStateQueueStats deliverDue(
      std::size_t event, unsigned d, NeighborStateCache &cache,
      NeighborObjectSequenceCache &sequenceCache) {
    SharedEndpointStateQueueStats stats;
    std::deque<SharedEndpointStateMessage> remaining;
    while (!messages_.empty()) {
      SharedEndpointStateMessage message = std::move(messages_.front());
      messages_.pop_front();
      if (message.dueEvent > event) {
        remaining.push_back(std::move(message));
        continue;
      }
      ++stats.delivered;
      if (message.receiver >= cache.size() ||
          message.sender >= cache[message.receiver].size() ||
          message.receiver >= sequenceCache.size() ||
          message.sender >= sequenceCache[message.receiver].size() ||
          message.object >= sequenceCache[message.receiver][message.sender].size()) {
        ++stats.stale;
        continue;
      }
      const std::size_t objectOffset = static_cast<std::size_t>(
          cache[message.receiver][message.sender].cols() / (d + 1u));
      (void)objectOffset;
      if (message.endpointSequence <=
          sequenceCache[message.receiver][message.sender][message.object]) {
        ++stats.stale;
        continue;
      }
      const std::size_t senderObjectIndex =
          inferObjectIndex(cache[message.receiver][message.sender],
                           sequenceCache[message.receiver][message.sender].size(),
                           message.object, d);
      cache[message.receiver][message.sender]
          .block(0, static_cast<Eigen::Index>(senderObjectIndex * (d + 1u)),
                 static_cast<Eigen::Index>(d), static_cast<Eigen::Index>(d + 1u)) =
          message.poseBlock;
      sequenceCache[message.receiver][message.sender][message.object] =
          message.endpointSequence;
    }
    messages_ = std::move(remaining);
    return stats;
  }

  std::size_t outstanding() const { return messages_.size(); }

 private:
  static std::size_t inferObjectIndex(const Matrix &state,
                                      std::size_t numObjects,
                                      std::size_t objectId, unsigned d) {
    const std::size_t totalBlocks =
        static_cast<std::size_t>(state.cols()) / (d + 1u);
    if (numObjects > totalBlocks) {
      return objectId;
    }
    return totalBlocks - numObjects + objectId;
  }

  std::deque<SharedEndpointStateMessage> messages_;
};

void mergeObjectExchangeStats(ObjectExchangeStats &target,
                              const ObjectExchangeStats &source) {
  target.communicated += source.communicated;
  target.payloadBytes += source.payloadBytes;
  target.staleObjectCommTriggers += source.staleObjectCommTriggers;
  for (std::size_t robotId = 0; robotId < source.selectedForSend.size();
       ++robotId) {
    if (robotId >= target.selectedForSend.size()) {
      break;
    }
    for (std::size_t objectId = 0;
         objectId < source.selectedForSend[robotId].size(); ++objectId) {
      if (objectId >= target.selectedForSend[robotId].size()) {
        break;
      }
      target.selectedForSend[robotId][objectId] =
          target.selectedForSend[robotId][objectId] ||
          source.selectedForSend[robotId][objectId];
    }
  }
  for (std::size_t receiverId = 0;
       receiverId < source.selectedForReceiver.size(); ++receiverId) {
    if (receiverId >= target.selectedForReceiver.size()) {
      break;
    }
    for (std::size_t senderId = 0;
         senderId < source.selectedForReceiver[receiverId].size();
         ++senderId) {
      if (senderId >= target.selectedForReceiver[receiverId].size()) {
        break;
      }
      for (std::size_t objectId = 0;
           objectId <
           source.selectedForReceiver[receiverId][senderId].size();
           ++objectId) {
        if (objectId >=
            target.selectedForReceiver[receiverId][senderId].size()) {
          break;
        }
        target.selectedForReceiver[receiverId][senderId][objectId] =
            target.selectedForReceiver[receiverId][senderId][objectId] ||
            source.selectedForReceiver[receiverId][senderId][objectId];
      }
    }
  }
}

