std::vector<std::string> splitCsvLine(const std::string &line) {
  std::vector<std::string> tokens;
  std::string token;
  std::stringstream ss(line);
  while (std::getline(ss, token, ',')) {
    tokens.push_back(token);
  }
  return tokens;
}

std::string trim(const std::string &value) {
  const std::size_t begin = value.find_first_not_of(" \t\r\n");
  if (begin == std::string::npos) {
    return "";
  }
  const std::size_t end = value.find_last_not_of(" \t\r\n");
  return value.substr(begin, end - begin + 1);
}

std::string lowerAscii(std::string value) {
  for (char &ch : value) {
    ch = static_cast<char>(
        std::tolower(static_cast<unsigned char>(ch)));
  }
  return value;
}

bool isSyntheticObjectSymmetryName(const std::string &value) {
  const std::string lower = lowerAscii(trim(value));
  return lower == "identity" || lower == "c2" || lower == "c4";
}

SyntheticObjectSymmetry parseSyntheticObjectSymmetryName(
    const std::string &value) {
  const std::string lower = lowerAscii(trim(value));
  if (lower == "c2") {
    return SyntheticObjectSymmetry::C2;
  }
  if (lower == "c4") {
    return SyntheticObjectSymmetry::C4;
  }
  return SyntheticObjectSymmetry::Identity;
}

std::size_t syntheticObjectSymmetryOrder(SyntheticObjectSymmetry symmetry) {
  switch (symmetry) {
    case SyntheticObjectSymmetry::C2:
      return 2;
    case SyntheticObjectSymmetry::C4:
      return 4;
    case SyntheticObjectSymmetry::Identity:
      return 1;
  }
  return 1;
}

std::size_t associationYawSymmetryOrder(
    const SyntheticObjectMetadataSet *metadata, std::size_t robotId,
    std::size_t targetRobotId, std::size_t localObjectId,
    std::size_t targetObjectId, const ManualObjectDranOptions &options) {
  if (!options.associationUseQuotientMetric || metadata == nullptr ||
      robotId >= metadata->observations.size() ||
      targetRobotId >= metadata->observations.size() ||
      localObjectId >= metadata->observations[robotId].size() ||
      targetObjectId >= metadata->observations[targetRobotId].size()) {
    return 1;
  }
  const SyntheticObjectSymmetry local =
      metadata->observations[robotId][localObjectId].symmetry;
  const SyntheticObjectSymmetry target =
      metadata->observations[targetRobotId][targetObjectId].symmetry;
  if (local != target) {
    return 1;
  }
  return syntheticObjectSymmetryOrder(local);
}

Matrix yawSymmetryRotation(unsigned dimension, std::size_t branch,
                           std::size_t order) {
  Matrix rotation = Matrix::Identity(dimension, dimension);
  if (order <= 1 || dimension < 2) {
    return rotation;
  }
  constexpr double kPi = 3.14159265358979323846264338327950288;
  const double theta =
      2.0 * kPi * static_cast<double>(branch % order) /
      static_cast<double>(order);
  const double c = std::cos(theta);
  const double s = std::sin(theta);
  rotation(0, 0) = c;
  rotation(0, 1) = -s;
  rotation(1, 0) = s;
  rotation(1, 1) = c;
  return rotation;
}

Matrix closestYawSymmetryPose(const Matrix &referencePose,
                              const Matrix &targetPose,
                              unsigned dimension,
                              std::size_t yawSymmetryOrder) {
  if (yawSymmetryOrder <= 1) {
    return targetPose;
  }
  Matrix best = targetPose;
  double bestCost = std::numeric_limits<double>::infinity();
  for (std::size_t branch = 0; branch < yawSymmetryOrder; ++branch) {
    Matrix candidate = targetPose;
    candidate.leftCols(static_cast<int>(dimension)).noalias() =
        targetPose.leftCols(static_cast<int>(dimension)) *
        yawSymmetryRotation(dimension, branch, yawSymmetryOrder);
    const double cost = (referencePose - candidate).squaredNorm();
    if (cost < bestCost) {
      bestCost = cost;
      best = std::move(candidate);
    }
  }
  return best;
}

bool associationBackendFeedbackEnabled(
    const ManualObjectDranOptions &options) {
  return std::isfinite(options.associationBackendFeedbackGradientScale) &&
         options.associationBackendFeedbackGradientScale > 0.0;
}

bool associationBackendResponseEnabled(
    const ManualObjectDranOptions &options) {
  return std::isfinite(options.associationBackendResponseGain) &&
         options.associationBackendResponseGain > 0.0;
}

bool associationBackendAdjointEnabled(
    const ManualObjectDranOptions &options) {
  return std::isfinite(options.associationBackendAdjointGain) &&
         options.associationBackendAdjointGain > 0.0;
}

bool associationBackendCoupledAdjointEnabled(
    const ManualObjectDranOptions &options) {
  return std::isfinite(options.associationBackendCoupledAdjointGain) &&
         options.associationBackendCoupledAdjointGain > 0.0;
}

bool associationBackendAdjointReductionGuardEnabled(
    const ManualObjectDranOptions &options,
    const SyntheticObjectMetadataSet *metadata) {
  return metadata != nullptr && options.associationUseSyntheticMetadata &&
         std::isfinite(
             options.associationBackendAdjointReductionMetadataMargin) &&
         options.associationBackendAdjointReductionMetadataMargin >= 0.0;
}

bool associationPairSupportGateEnabled(
    const ManualObjectDranOptions &options) {
  return std::isfinite(options.associationPairSupportGatePower) &&
         options.associationPairSupportGatePower > 0.0;
}

bool associationPairSupportLatentContinuationEnabled(
    const ManualObjectDranOptions &options) {
  return options.associationPairSupportLatentContinuation;
}

double associationPairSupportGateMinEffectiveSupport(
    const ManualObjectDranOptions &options) {
  if (std::isfinite(options.associationPairSupportGateMinEffectiveSupport) &&
      options.associationPairSupportGateMinEffectiveSupport > 0.0) {
    return options.associationPairSupportGateMinEffectiveSupport;
  }
  return std::max(1.0,
                  static_cast<double>(options.associationTransformMinInliers));
}

double objectBackendGradientNorm(
    const ObjectBackendGradientNorms *backendGradientNorms,
    std::size_t robotId, std::size_t objectId) {
  if (backendGradientNorms == nullptr ||
      robotId >= backendGradientNorms->size() ||
      objectId >= (*backendGradientNorms)[robotId].size()) {
    return 0.0;
  }
  const double value = (*backendGradientNorms)[robotId][objectId];
  return std::isfinite(value) && value > 0.0 ? value : 0.0;
}

const Matrix *objectBackendGradientBlock(
    const ObjectBackendResponseData *backendResponseData,
    std::size_t robotId, std::size_t objectId) {
  if (backendResponseData == nullptr ||
      robotId >= backendResponseData->gradients.size() ||
      objectId >= backendResponseData->gradients[robotId].size()) {
    return nullptr;
  }
  const Matrix &gradient =
      backendResponseData->gradients[robotId][objectId];
  return gradient.size() > 0 && gradient.allFinite() ? &gradient : nullptr;
}

const Matrix *objectBackendAdjointBlock(
    const ObjectBackendResponseData *backendResponseData,
    std::size_t robotId, std::size_t objectId) {
  if (backendResponseData == nullptr ||
      robotId >= backendResponseData->adjoints.size() ||
      objectId >= backendResponseData->adjoints[robotId].size()) {
    return nullptr;
  }
  const Matrix &adjoint =
      backendResponseData->adjoints[robotId][objectId];
  return adjoint.size() > 0 && adjoint.allFinite() ? &adjoint : nullptr;
}

double objectBackendResponseStiffness(
    const ObjectBackendResponseData *backendResponseData,
    std::size_t robotId, std::size_t objectId) {
  if (backendResponseData == nullptr ||
      robotId >= backendResponseData->stiffness.size() ||
      objectId >= backendResponseData->stiffness[robotId].size()) {
    return 0.0;
  }
  const double value = backendResponseData->stiffness[robotId][objectId];
  return std::isfinite(value) && value > 0.0 ? value : 0.0;
}

double matrixDot(const Matrix &lhs, const Matrix &rhs) {
  if (lhs.rows() != rhs.rows() || lhs.cols() != rhs.cols() ||
      !lhs.allFinite() || !rhs.allFinite()) {
    return 0.0;
  }
  return (lhs.array() * rhs.array()).sum();
}

std::vector<double> rowBestFiniteCosts(const Matrix &costs) {
  std::vector<double> best(static_cast<std::size_t>(costs.rows()),
                           std::numeric_limits<double>::infinity());
  for (int row = 0; row < costs.rows(); ++row) {
    for (int col = 0; col < costs.cols(); ++col) {
      const double value = costs(row, col);
      if (std::isfinite(value)) {
        best[static_cast<std::size_t>(row)] =
            std::min(best[static_cast<std::size_t>(row)], value);
      }
    }
  }
  return best;
}

std::vector<double> colBestFiniteCosts(const Matrix &costs) {
  std::vector<double> best(static_cast<std::size_t>(costs.cols()),
                           std::numeric_limits<double>::infinity());
  for (int row = 0; row < costs.rows(); ++row) {
    for (int col = 0; col < costs.cols(); ++col) {
      const double value = costs(row, col);
      if (std::isfinite(value)) {
        best[static_cast<std::size_t>(col)] =
            std::min(best[static_cast<std::size_t>(col)], value);
      }
    }
  }
  return best;
}

bool metadataAllowsBackendAdjointCostReduction(
    const Matrix &metadataCosts, const std::vector<double> &rowBest,
    const std::vector<double> &colBest, std::size_t row, std::size_t col,
    double margin) {
  if (row >= rowBest.size() || col >= colBest.size() ||
      row >= static_cast<std::size_t>(metadataCosts.rows()) ||
      col >= static_cast<std::size_t>(metadataCosts.cols()) ||
      !std::isfinite(margin)) {
    return false;
  }
  const double candidate =
      metadataCosts(static_cast<int>(row), static_cast<int>(col));
  if (!std::isfinite(candidate) || !std::isfinite(rowBest[row]) ||
      !std::isfinite(colBest[col])) {
    return false;
  }
  return candidate <= rowBest[row] + margin &&
         candidate <= colBest[col] + margin;
}

DirectedAssociationWeights makeZeroDirectedAssociationWeights(
    std::size_t numRobots, std::size_t numObjects) {
  DirectedAssociationWeights weights(
      numRobots, std::vector<Matrix>(numRobots));
  for (std::size_t receiver = 0; receiver < numRobots; ++receiver) {
    for (std::size_t sender = 0; sender < numRobots; ++sender) {
      weights[receiver][sender] =
          Matrix::Zero(numObjects, numObjects);
    }
  }
  return weights;
}

AssociationIdentityActiveSet fixedIdentityActiveSet(
    const Matrix &weights, double rowCapacity, double columnCapacity) {
  AssociationIdentityActiveSet active;
  const double identityCapacity = std::min(rowCapacity, columnCapacity);
  if (!std::isfinite(identityCapacity) || identityCapacity <= 0.0) {
    return active;
  }
  for (Eigen::Index row = 0; row < weights.rows(); ++row) {
    for (Eigen::Index col = 0; col < weights.cols(); ++col) {
      if (std::isfinite(weights(row, col)) &&
          weights(row, col) == identityCapacity) {
        active.insert({static_cast<std::size_t>(row),
                       static_cast<std::size_t>(col)});
      }
    }
  }
  return active;
}

void initializeFixedIdentityActiveSets(
    const DirectedAssociationWeights &weights, double rowCapacity,
    double columnCapacity,
    DirectedAssociationIdentityActiveSets &activeSets) {
  activeSets.assign(
      weights.size(),
      std::vector<AssociationIdentityActiveSet>(weights.size()));
  for (std::size_t receiver = 0; receiver < weights.size(); ++receiver) {
    for (std::size_t sender = 0; sender < weights[receiver].size(); ++sender) {
      activeSets[receiver][sender] = fixedIdentityActiveSet(
          weights[receiver][sender], rowCapacity, columnCapacity);
    }
  }
}

DirectedAssociationScalars makeZeroDirectedAssociationScalars(
    std::size_t numRobots) {
  return DirectedAssociationScalars(
      numRobots, std::vector<double>(numRobots, 0.0));
}

DirectedAssociationScalars makeUnitDirectedAssociationScalars(
    std::size_t numRobots) {
  return DirectedAssociationScalars(
      numRobots, std::vector<double>(numRobots, 1.0));
}

double directedAssociationScalar(
    const DirectedAssociationScalars *scalars, std::size_t receiverId,
    std::size_t senderId, double fallback) {
  if (scalars == nullptr || receiverId >= scalars->size() ||
      senderId >= (*scalars)[receiverId].size()) {
    return fallback;
  }
  const double value = (*scalars)[receiverId][senderId];
  return std::isfinite(value) ? value : fallback;
}

double associationPairValidationTrustForUse(
    const DirectedAssociationScalars *associationPairValidationTrust,
    std::size_t receiverId, std::size_t senderId) {
  return std::clamp(
      directedAssociationScalar(associationPairValidationTrust, receiverId,
                                senderId, 1.0),
      0.0, 1.0);
}

DirectedAssociationReliabilities makeUnitDirectedAssociationReliabilities(
    std::size_t numRobots, std::size_t numObjects) {
  DirectedAssociationReliabilities reliabilities(
      numRobots, std::vector<Matrix>(numRobots));
  for (std::size_t receiver = 0; receiver < numRobots; ++receiver) {
    for (std::size_t sender = 0; sender < numRobots; ++sender) {
      reliabilities[receiver][sender] =
          Matrix::Ones(numObjects, numObjects);
    }
  }
  return reliabilities;
}

DirectedUpperTrackingStates makeDirectedUpperTrackingStates(
    std::size_t numRobots) {
  return DirectedUpperTrackingStates(
      numRobots, std::vector<DistributedUpperTrackingState>(numRobots));
}

DirectedAssociationTransforms makeEmptyDirectedAssociationTransforms(
    std::size_t numRobots) {
  return DirectedAssociationTransforms(
      numRobots, std::vector<AssociationTransform>(numRobots));
}

bool usesExternallyInitializedFrozenDbaAssociation(
    const ManualObjectDranOptions &options) {
  return options.associationPolicy ==
             ManualObjectDranAssociationPolicy::DecentralizedFeedbackUotDbaV1 &&
         options.associationFreezeUpperVariables &&
         !options.associationFile.empty();
}

DirectedAssociationWeights loadDirectedAssociationWeights(
    const ObjectPGODirectoryData &dataset,
    const ManualObjectDranOptions &options) {
  DirectedAssociationWeights weights =
      makeZeroDirectedAssociationWeights(dataset.numRobots,
                                         dataset.numObjects);
  if (options.associationMode ==
      ManualObjectDranAssociationMode::IdentityOracle) {
    const Matrix identity = Matrix::Identity(
        static_cast<Eigen::Index>(dataset.numObjects),
        static_cast<Eigen::Index>(dataset.numObjects));
    for (std::size_t receiver = 0; receiver < dataset.numRobots; ++receiver) {
      for (std::size_t sender = 0; sender < dataset.numRobots; ++sender) {
        if (receiver != sender) {
          weights[receiver][sender] = identity;
        }
      }
    }
    return weights;
  }
  if (options.associationMode !=
          ManualObjectDranAssociationMode::FixedFileSoft &&
      !usesExternallyInitializedFrozenDbaAssociation(options)) {
    return weights;
  }
  if (options.associationFile.empty()) {
    throw std::runtime_error(
        "FixedFileSoft association mode requires --association_file");
  }

  std::ifstream in(options.associationFile);
  if (!in.is_open()) {
    throw std::runtime_error("Could not open association file: " +
                             options.associationFile);
  }

  std::string line;
  std::size_t lineNumber = 0;
  while (std::getline(in, line)) {
    ++lineNumber;
    const std::string stripped = trim(line);
    if (stripped.empty() || stripped[0] == '#') {
      continue;
    }
    std::vector<std::string> tokens = splitCsvLine(stripped);
    for (std::string &token : tokens) {
      token = trim(token);
    }
    if (!tokens.empty() &&
        (tokens.front() == "receiver_robot" ||
         tokens.front() == "receiver" || tokens.front() == "src_robot")) {
      continue;
    }
    if (tokens.size() < 5) {
      throw std::runtime_error(
          "Association file row must have at least 5 columns at line " +
          std::to_string(lineNumber));
    }
    const std::size_t receiverRobot =
        static_cast<std::size_t>(std::stoul(tokens[0]));
    const std::size_t senderRobot =
        static_cast<std::size_t>(std::stoul(tokens[1]));
    const std::size_t receiverObject =
        static_cast<std::size_t>(std::stoul(tokens[2]));
    const std::size_t senderObject =
        static_cast<std::size_t>(std::stoul(tokens[3]));
    const double weight = std::stod(tokens[4]);
    if (receiverRobot >= dataset.numRobots ||
        senderRobot >= dataset.numRobots ||
        receiverObject >= dataset.numObjects ||
        senderObject >= dataset.numObjects) {
      throw std::runtime_error(
          "Association file index out of range at line " +
          std::to_string(lineNumber));
    }
    if (!std::isfinite(weight) || weight < 0.0) {
      throw std::runtime_error(
          "Association file weight must be finite and nonnegative at line " +
          std::to_string(lineNumber));
    }
    weights[receiverRobot][senderRobot](
        static_cast<int>(receiverObject),
        static_cast<int>(senderObject)) = weight;
  }
  return weights;
}

DirectedAssociationWeights loadGroundTruthAssociationWeights(
    const ObjectPGODirectoryData &dataset, const std::string &directory) {
  DirectedAssociationWeights weights =
      makeZeroDirectedAssociationWeights(dataset.numRobots,
                                         dataset.numObjects);
  const std::filesystem::path path =
      std::filesystem::path(directory) / "gt_associations.csv";
  if (!std::filesystem::exists(path)) {
    return weights;
  }
  std::ifstream in(path);
  if (!in.is_open()) {
    throw std::runtime_error("Could not open ground-truth association file: " +
                             path.string());
  }
  std::string line;
  std::size_t lineNumber = 0;
  while (std::getline(in, line)) {
    ++lineNumber;
    const std::string stripped = trim(line);
    if (stripped.empty() || stripped[0] == '#') {
      continue;
    }
    std::vector<std::string> tokens = splitCsvLine(stripped);
    for (std::string &token : tokens) {
      token = trim(token);
    }
    if (!tokens.empty() &&
        (tokens.front() == "receiver_robot" || tokens.front() == "receiver")) {
      continue;
    }
    if (tokens.size() < 5) {
      throw std::runtime_error(
          "Ground-truth association row must have at least 5 columns at line " +
          std::to_string(lineNumber));
    }
    const std::size_t receiverRobot =
        static_cast<std::size_t>(std::stoul(tokens[0]));
    const std::size_t senderRobot =
        static_cast<std::size_t>(std::stoul(tokens[1]));
    const std::size_t receiverObject =
        static_cast<std::size_t>(std::stoul(tokens[2]));
    const std::size_t senderObject =
        static_cast<std::size_t>(std::stoul(tokens[3]));
    const double weight = std::stod(tokens[4]);
    if (receiverRobot >= dataset.numRobots ||
        senderRobot >= dataset.numRobots ||
        receiverObject >= dataset.numObjects ||
        senderObject >= dataset.numObjects) {
      throw std::runtime_error(
          "Ground-truth association index out of range at line " +
          std::to_string(lineNumber));
    }
    if (!std::isfinite(weight) || weight < 0.0) {
      throw std::runtime_error(
          "Ground-truth association weight must be finite and nonnegative at line " +
          std::to_string(lineNumber));
    }
    weights[receiverRobot][senderRobot](
        static_cast<int>(receiverObject),
        static_cast<int>(senderObject)) = weight;
  }
  return weights;
}

bool tryLoadLocalObjectMetadataForAssociation(
    const ObjectPGODirectoryData &dataset, const std::string &directory,
    SyntheticObjectMetadataSet &metadata) {
  const std::filesystem::path path =
      std::filesystem::path(directory) / "local_object_metadata.csv";
  if (!std::filesystem::exists(path)) {
    return false;
  }

  std::ifstream in(path);
  if (!in.is_open()) {
    throw std::runtime_error("Could not open local object metadata file: " +
                             path.string());
  }

  metadata.objects.clear();
  metadata.objects.resize(dataset.numObjects);
  metadata.observations.assign(
      dataset.numRobots,
      std::vector<SyntheticObjectObservationMetadata>(dataset.numObjects));
  std::vector<std::vector<bool>> seen(
      dataset.numRobots, std::vector<bool>(dataset.numObjects, false));
  std::size_t descriptorDim = 0;
  bool descriptorDimKnown = false;

  std::string line;
  std::size_t lineNumber = 0;
  while (std::getline(in, line)) {
    ++lineNumber;
    const std::string stripped = trim(line);
    if (stripped.empty() || stripped[0] == '#') {
      continue;
    }
    std::vector<std::string> tokens = splitCsvLine(stripped);
    for (std::string &token : tokens) {
      token = trim(token);
    }
    if (!tokens.empty() &&
        (tokens.front() == "robot_id" || tokens.front() == "robot")) {
      continue;
    }
    if (tokens.size() < 9) {
      throw std::runtime_error(
          "Local object metadata row must have at least 9 columns at line " +
          std::to_string(lineNumber));
    }

    const std::size_t robotId =
        static_cast<std::size_t>(std::stoul(tokens[0]));
    const std::size_t localObjectId =
        static_cast<std::size_t>(std::stoul(tokens[1]));
    if (robotId >= dataset.numRobots || localObjectId >= dataset.numObjects) {
      throw std::runtime_error(
          "Local object metadata index out of range at line " +
          std::to_string(lineNumber));
    }

    const bool hasSymmetryColumn =
        tokens.size() >= 10 && isSyntheticObjectSymmetryName(tokens[5]);
    const std::size_t semanticIndex = hasSymmetryColumn ? 6 : 5;
    const std::size_t shapeIndex = hasSymmetryColumn ? 7 : 6;
    const std::size_t descriptorIndex = hasSymmetryColumn ? 10 : 9;
    const std::size_t rowDescriptorDim = tokens.size() - descriptorIndex;
    if (!descriptorDimKnown) {
      descriptorDim = rowDescriptorDim;
      descriptorDimKnown = true;
    } else if (rowDescriptorDim != descriptorDim) {
      throw std::runtime_error(
          "Local object metadata descriptor dimension mismatch at line " +
          std::to_string(lineNumber));
    }

    SyntheticObjectObservationMetadata observation;
    observation.robotId = robotId;
    observation.objectId = localObjectId;
    observation.category =
        static_cast<std::size_t>(std::stoul(tokens[4]));
    observation.symmetry =
        hasSymmetryColumn ? parseSyntheticObjectSymmetryName(tokens[5])
                          : SyntheticObjectSymmetry::Identity;
    observation.semanticConfidence = std::stod(tokens[semanticIndex]);
    observation.shape = Vector::Zero(3);
    observation.shape(0) = std::stod(tokens[shapeIndex]);
    observation.shape(1) = std::stod(tokens[shapeIndex + 1]);
    observation.shape(2) = std::stod(tokens[shapeIndex + 2]);
    observation.descriptor =
        Vector::Zero(static_cast<int>(rowDescriptorDim));
    for (std::size_t dim = 0; dim < rowDescriptorDim; ++dim) {
      observation.descriptor(static_cast<int>(dim)) =
          std::stod(tokens[descriptorIndex + dim]);
    }
    metadata.observations[robotId][localObjectId] = std::move(observation);
    seen[robotId][localObjectId] = true;
  }

  for (std::size_t robotId = 0; robotId < dataset.numRobots; ++robotId) {
    for (std::size_t objectId = 0; objectId < dataset.numObjects;
         ++objectId) {
      if (!seen[robotId][objectId]) {
        throw std::runtime_error(
            "Local object metadata file is missing robot/object entry");
      }
      if (robotId == 0) {
        const SyntheticObjectObservationMetadata &observation =
            metadata.observations[robotId][objectId];
        metadata.objects[objectId].category = observation.category;
        metadata.objects[objectId].symmetry = observation.symmetry;
        metadata.objects[objectId].shape = observation.shape;
        metadata.objects[objectId].descriptor = observation.descriptor;
      }
    }
  }
  return true;
}

void addWeightedNeighbor(std::vector<WeightedNeighbor> &neighbors,
                         unsigned id, double weight) {
  for (WeightedNeighbor &neighbor : neighbors) {
    if (neighbor.id == id) {
      neighbor.weight = weight;
      return;
    }
  }
  neighbors.push_back(WeightedNeighbor{id, weight});
}

enum class LocalMeasurementSubset {
  All,
  Train,
  HeldoutOnly,
};

bool heldoutObjectObservationSelectionEnabled(
    const ManualObjectDranOptions *options) {
  return options != nullptr &&
         options->associationHeldoutObjectObservationModulo > 1u;
}

bool primaryLowerHeldoutSplitEnabled(
    const ManualObjectDranOptions *options) {
  return options != nullptr &&
         options->associationHeldoutObjectObservationModulo > 1u;
}

bool isHeldoutObjectObservation(
    const ManualObjectDranOptions *options, std::size_t observationIndex) {
  if (!heldoutObjectObservationSelectionEnabled(options)) {
    return false;
  }
  const std::size_t modulo =
      options->associationHeldoutObjectObservationModulo;
  return observationIndex % modulo ==
         options->associationHeldoutObjectObservationRemainder % modulo;
}

struct ObjectObservationTrackEmpiricalScaleResult {
  std::vector<double> observationScales;
  std::vector<TrackEmpiricalInformationEstimate> trackEstimates;
};

ObjectObservationTrackEmpiricalScaleResult
objectObservationTrackEmpiricalScales(const ObjectPGORobotData &robot,
                                      const Matrix &state, unsigned d) {
  ObjectObservationTrackEmpiricalScaleResult result;
  result.observationScales.assign(robot.objectObservationMeasurements.size(),
                                  1.0);
  if (d == 0) {
    return result;
  }

  std::map<std::size_t, std::vector<std::size_t>> trackObservationIndices;
  for (std::size_t index = 0;
       index < robot.objectObservationMeasurements.size(); ++index) {
    trackObservationIndices[robot.objectObservationMeasurements[index]
                                .objectLocalIndex]
        .push_back(index);
  }

  result.trackEstimates.reserve(trackObservationIndices.size());
  for (const auto &track : trackObservationIndices) {
    std::vector<Vector> centers;
    std::vector<double> information;
    centers.reserve(track.second.size());
    information.reserve(track.second.size());
    for (std::size_t observationIndex : track.second) {
      const ObjectObservationMeasurement &observation =
          robot.objectObservationMeasurements[observationIndex];
      const Matrix implied =
          objectObservationImpliedPose(state, observation, d);
      if (implied.rows() == static_cast<int>(d) &&
          implied.cols() == static_cast<int>(d + 1) &&
          implied.allFinite()) {
        centers.push_back(implied.col(static_cast<int>(d)));
      } else {
        centers.push_back(Vector::Constant(
            d, std::numeric_limits<double>::quiet_NaN()));
      }
      information.push_back(observation.measurement.tau);
    }
    const TrackEmpiricalInformationEstimate estimate =
        estimateTrackEmpiricalInformation(centers, information);
    result.trackEstimates.push_back(estimate);
    for (std::size_t observationIndex : track.second) {
      result.observationScales[observationIndex] =
          estimate.informationScale;
    }
  }
  return result;
}

std::vector<RelativeSEMeasurement> objectAwareLocalMeasurements(
    const ObjectPGORobotData &robot, const Matrix *state = nullptr,
    unsigned d = 0, const ManualObjectDranOptions *options = nullptr,
    LocalMeasurementSubset subset = LocalMeasurementSubset::All) {
  std::vector<RelativeSEMeasurement> measurements =
      subset == LocalMeasurementSubset::HeldoutOnly
          ? std::vector<RelativeSEMeasurement>()
          : robot.trajectoryMeasurements;
  measurements.reserve(measurements.size() +
                       robot.objectObservationMeasurements.size());

  const auto makeLocalObjectMeasurement =
      [&robot](const ObjectObservationMeasurement &obs) {
        RelativeSEMeasurement m = obs.measurement;
        m.p1 = obs.trajectoryLocalIndex;
        m.p2 = robot.trajectoryVertexIds.size() + obs.objectLocalIndex;
        m.r1 = robot.robotId;
        m.r2 = robot.robotId;
        return m;
      };

  const double robustResidualScale =
      options != nullptr
          ? options->associationObjectObservationRobustResidualScale
          : 0.0;
  const bool robustObjectObservations =
      state != nullptr && options != nullptr && d > 0 &&
      std::isfinite(robustResidualScale) && robustResidualScale != 0.0;
  const bool useActiveRmsRobustScale = robustResidualScale < 0.0;
  std::vector<double> informationScales(
      robot.objectObservationMeasurements.size(), 1.0);
  if (robustObjectObservations) {
    std::vector<double> residualNorms(
        robot.objectObservationMeasurements.size(), 0.0);
    for (std::size_t idx = 0;
         idx < robot.objectObservationMeasurements.size(); ++idx) {
      const RelativeSEMeasurement localMeasurement =
          makeLocalObjectMeasurement(robot.objectObservationMeasurements[idx]);
      residualNorms[idx] = std::sqrt(
          std::max(0.0, measurementCost(localMeasurement, *state, d)));
    }
    if (useActiveRmsRobustScale) {
      informationScales = objectResidualReliabilityVectorFromActiveRms(
          residualNorms,
          options->associationObjectObservationRobustMinInformationScale);
    } else {
      for (std::size_t idx = 0;
           idx < robot.objectObservationMeasurements.size(); ++idx) {
        informationScales[idx] = objectCopyResidualReliability(
            residualNorms[idx], robustResidualScale,
            options->associationObjectObservationRobustMinInformationScale);
      }
    }
    double scaleSum = 0.0;
    std::size_t scaleCount = 0;
    for (std::size_t idx = 0;
         idx < robot.objectObservationMeasurements.size(); ++idx) {
      if (std::isfinite(informationScales[idx]) &&
          informationScales[idx] > 0.0) {
        scaleSum += informationScales[idx];
        ++scaleCount;
      }
    }
    if (options->associationObjectObservationRobustNormalizeInformation &&
        scaleCount > 0 && scaleSum > 0.0) {
      const double meanScale = scaleSum / static_cast<double>(scaleCount);
      for (double &scale : informationScales) {
        scale /= meanScale;
      }
    }
  }
  std::vector<double> trackEmpiricalScales(
      robot.objectObservationMeasurements.size(), 1.0);
  const bool trackEmpiricalInformation =
      state != nullptr && options != nullptr && d > 0 &&
      options->associationObjectObservationTrackEmpiricalInformation;
  if (trackEmpiricalInformation) {
    trackEmpiricalScales =
        objectObservationTrackEmpiricalScales(robot, *state, d)
            .observationScales;
  }

  for (std::size_t idx = 0; idx < robot.objectObservationMeasurements.size();
       ++idx) {
    const bool heldout = isHeldoutObjectObservation(options, idx);
    if (subset == LocalMeasurementSubset::Train && heldout) {
      continue;
    }
    if (subset == LocalMeasurementSubset::HeldoutOnly && !heldout) {
      continue;
    }
    const ObjectObservationMeasurement &obs =
        robot.objectObservationMeasurements[idx];
    RelativeSEMeasurement m = obs.measurement;
    m = makeLocalObjectMeasurement(obs);
    if (options != nullptr && !options->objectOrientationObserved) {
      m.kappa = 0.0;
    }
    if (robustObjectObservations && idx < informationScales.size()) {
      m.kappa *= informationScales[idx];
      m.tau *= informationScales[idx];
    }
    if (trackEmpiricalInformation && idx < trackEmpiricalScales.size()) {
      m.tau *= trackEmpiricalScales[idx];
    }
    measurements.push_back(std::move(m));
  }
  return measurements;
}

SparseMatrix fullConnectionLaplacian(
    const std::vector<RelativeSEMeasurement> &measurements,
    std::size_t numPoses, unsigned d) {
  SparseMatrix full((d + 1) * numPoses, (d + 1) * numPoses);
  if (measurements.empty()) {
    return full;
  }
  const SparseMatrix compact = constructConnectionLaplacianSE(measurements);
  std::vector<Eigen::Triplet<double>> triplets;
  triplets.reserve(static_cast<std::size_t>(compact.nonZeros()));
  for (int outer = 0; outer < compact.outerSize(); ++outer) {
    for (SparseMatrix::InnerIterator it(compact, outer); it; ++it) {
      if (it.row() < full.rows() && it.col() < full.cols()) {
        triplets.emplace_back(it.row(), it.col(), it.value());
      }
    }
  }
  full.setFromTriplets(triplets.begin(), triplets.end());
  full.makeCompressed();
  return full;
}

bool objectObservationRobustWeightsDependOnState(
    const ManualObjectDranOptions &options) {
  const double scale =
      options.associationObjectObservationRobustResidualScale;
  return std::isfinite(scale) && scale != 0.0;
}

SparseMatrix objectAwareLocalBaseQ(const ObjectPGORobotData &robot,
                                   const Matrix &state, std::size_t numObjects,
                                   unsigned d,
                                   const ManualObjectDranOptions &options) {
  const std::vector<RelativeSEMeasurement> measurements =
      objectAwareLocalMeasurements(
          robot, &state, d, &options,
          primaryLowerHeldoutSplitEnabled(&options)
              ? LocalMeasurementSubset::Train
              : LocalMeasurementSubset::All);
  const std::size_t localNumPoses =
      robot.trajectoryVertexIds.size() + numObjects;
  return fullConnectionLaplacian(measurements, localNumPoses, d);
}

Matrix assembleObjectAwareChordalState(
    const ObjectPGODirectoryData &dataset, std::size_t robotId,
    const Matrix &globalT, const std::vector<std::size_t> &trajectoryOffsets,
    std::size_t objectOffset, unsigned d) {
  const ObjectPGORobotData &robot = dataset.robots[robotId];
  const std::size_t localNumPoses =
      robot.trajectoryVertexIds.size() + dataset.numObjects;
  Matrix state = Matrix::Zero(d, localNumPoses * (d + 1));
  for (std::size_t localIdx = 0; localIdx < robot.trajectoryVertexIds.size();
       ++localIdx) {
    const std::size_t globalIdx = trajectoryOffsets[robotId] + localIdx;
    state.block(0, localIdx * (d + 1), d, d + 1) =
        globalT.block(0, globalIdx * (d + 1), d, d + 1);
  }
  for (std::size_t objectId = 0; objectId < dataset.numObjects; ++objectId) {
    const std::size_t localIdx = robot.trajectoryVertexIds.size() + objectId;
    const std::size_t globalIdx = objectOffset + objectId;
    state.block(0, localIdx * (d + 1), d, d + 1) =
        globalT.block(0, globalIdx * (d + 1), d, d + 1);
  }
  return state;
}

std::vector<Matrix> centralizedObjectAwareChordalStates(
    const ObjectPGODirectoryData &dataset, unsigned d) {
  std::vector<std::size_t> trajectoryOffsets(dataset.robots.size(), 0);
  std::size_t trajectoryCount = 0;
  for (std::size_t robotId = 0; robotId < dataset.robots.size(); ++robotId) {
    trajectoryOffsets[robotId] = trajectoryCount;
    trajectoryCount += dataset.robots[robotId].trajectoryVertexIds.size();
  }
  const std::size_t objectOffset = trajectoryCount;
  const std::size_t totalPoses = trajectoryCount + dataset.numObjects;

  std::vector<RelativeSEMeasurement> globalMeasurements;
  for (std::size_t robotId = 0; robotId < dataset.robots.size(); ++robotId) {
    const ObjectPGORobotData &robot = dataset.robots[robotId];
    for (RelativeSEMeasurement m : robot.trajectoryMeasurements) {
      m.p1 = trajectoryOffsets[robotId] + m.p1;
      m.p2 = trajectoryOffsets[robotId] + m.p2;
      m.r1 = 0;
      m.r2 = 0;
      globalMeasurements.push_back(std::move(m));
    }
    for (const ObjectObservationMeasurement &obs :
         robot.objectObservationMeasurements) {
      RelativeSEMeasurement m = obs.measurement;
      m.p1 = trajectoryOffsets[robotId] + obs.trajectoryLocalIndex;
      m.p2 = objectOffset + obs.objectGlobalVertexId;
      m.r1 = 0;
      m.r2 = 0;
      globalMeasurements.push_back(std::move(m));
    }
  }

  const Matrix globalT = chordalInitialization(d, totalPoses, globalMeasurements);
  std::vector<Matrix> states;
  states.reserve(dataset.robots.size());
  for (std::size_t robotId = 0; robotId < dataset.robots.size(); ++robotId) {
    states.push_back(assembleObjectAwareChordalState(
        dataset, robotId, globalT, trajectoryOffsets, objectOffset, d));
  }
  return states;
}

NeighborRound makeRingNeighbors(unsigned numRobots, unsigned hops) {
  NeighborRound neighbors(numRobots);
  if (numRobots < 2) {
    return neighbors;
  }
  hops = std::max(1u, std::min(hops, numRobots - 1));
  for (unsigned robotId = 0; robotId < numRobots; ++robotId) {
    for (unsigned offset = 1; offset <= hops; ++offset) {
      const unsigned prev = (robotId + numRobots - offset) % numRobots;
      const unsigned next = (robotId + offset) % numRobots;
      auto add = [&](unsigned id) {
        if (id != robotId) {
          addWeightedNeighbor(neighbors[robotId], id, 1.0);
        }
      };
      add(prev);
      add(next);
    }
  }
  return neighbors;
}

NeighborRound makeCompleteNeighbors(unsigned numRobots) {
  NeighborRound neighbors(numRobots);
  for (unsigned robotId = 0; robotId < numRobots; ++robotId) {
    for (unsigned other = 0; other < numRobots; ++other) {
      if (other != robotId) {
        addWeightedNeighbor(neighbors[robotId], other, 1.0);
      }
    }
  }
  return neighbors;
}

std::vector<NeighborRound> readTopologySchedule(
    const std::string &path, unsigned numRobots,
    const std::string &weightMode) {
  std::vector<NeighborRound> schedule;
  if (path.empty()) {
    return schedule;
  }
  std::ifstream input(path);
  if (!input.is_open()) {
    throw std::runtime_error("Could not open communication topology file: " +
                             path);
  }
  std::string line;
  while (std::getline(input, line)) {
    if (line.empty() || line[0] == '#') {
      continue;
    }
    const std::vector<std::string> tokens = splitCsvLine(line);
    if (tokens.size() < 4 || tokens[0] == "round") {
      continue;
    }
    const unsigned roundIdx =
        static_cast<unsigned>(std::stoul(tokens[0]));
    const unsigned src = static_cast<unsigned>(std::stoul(tokens[1]));
    const unsigned dst = static_cast<unsigned>(std::stoul(tokens[2]));
    double weight = std::stod(tokens[3]);
    if (weightMode == "unit") {
      weight = 1.0;
    } else if (weightMode != "matrix") {
      throw std::runtime_error("Unsupported communication weight mode: " +
                               weightMode);
    }
    if (!std::isfinite(weight) || weight <= 0.0 || weight > 1.0) {
      throw std::runtime_error("Invalid communication weight in " + path);
    }
    if (src >= numRobots || dst >= numRobots || src == dst) {
      throw std::runtime_error("Invalid communication edge in " + path);
    }
    if (schedule.size() <= roundIdx) {
      schedule.resize(roundIdx + 1, NeighborRound(numRobots));
    }
    addWeightedNeighbor(schedule[roundIdx][src], dst, weight);
    addWeightedNeighbor(schedule[roundIdx][dst], src, weight);
  }
  for (std::size_t roundIdx = 0; roundIdx < schedule.size(); ++roundIdx) {
    bool hasEdge = false;
    for (const std::vector<WeightedNeighbor> &neighbors : schedule[roundIdx]) {
      if (!neighbors.empty()) {
        hasEdge = true;
        break;
      }
    }
    if (!hasEdge) {
      throw std::runtime_error(
          "Communication topology rounds must be zero-based and contiguous: " +
          path);
    }
  }
  return schedule;
}

NeighborRound unionNeighbors(const std::vector<NeighborRound> &schedule,
                             unsigned numRobots) {
  NeighborRound result(numRobots);
  for (const NeighborRound &round : schedule) {
    if (round.size() != numRobots) {
      throw std::runtime_error("Invalid topology schedule round size");
    }
    for (unsigned robotId = 0; robotId < numRobots; ++robotId) {
      for (const WeightedNeighbor &neighbor : round[robotId]) {
        addWeightedNeighbor(result[robotId], neighbor.id, neighbor.weight);
      }
    }
  }
  return result;
}

std::vector<NeighborRound> makeTopologySchedule(
    unsigned numRobots, const ManualObjectDranOptions &options) {
  std::vector<NeighborRound> schedule =
      readTopologySchedule(options.topologyFile, numRobots,
                           options.topologyWeightMode);
  if (!options.topologyFile.empty() && schedule.empty()) {
    throw std::runtime_error("Communication topology file has no edges: " +
                             options.topologyFile);
  }
  if (!schedule.empty()) {
    return schedule;
  }
  schedule.push_back(options.topology == ManualObjectDranTopology::Complete
                         ? makeCompleteNeighbors(numRobots)
                         : makeRingNeighbors(numRobots, options.ringHops));
  return schedule;
}

std::vector<bool> observedObjects(const ObjectPGORobotData &robot,
                                  std::size_t numObjects) {
  std::vector<bool> observed(numObjects, false);
  for (const ObjectObservationMeasurement &obs :
       robot.objectObservationMeasurements) {
    if (obs.objectGlobalVertexId < numObjects) {
      observed[obs.objectGlobalVertexId] = true;
    }
  }
  return observed;
}

double associationRecallDenominatorForPair(
    const ObjectPGODirectoryData &dataset, std::size_t receiverId,
    std::size_t senderId, const ManualObjectDranOptions &options,
    const Matrix &groundTruth, bool groundTruthAvailable) {
  if (receiverId >= dataset.robots.size() ||
      senderId >= dataset.robots.size()) {
    return 0.0;
  }

  const bool observedOnly = options.associationRequireObservedObjects;
  std::vector<bool> receiverObserved;
  std::vector<bool> senderObserved;
  if (observedOnly) {
    receiverObserved =
        observedObjects(dataset.robots[receiverId], dataset.numObjects);
    senderObserved =
        observedObjects(dataset.robots[senderId], dataset.numObjects);
  }
  auto isEligible = [&](int row, int col) {
    return !observedOnly ||
           (row >= 0 && col >= 0 &&
            static_cast<std::size_t>(row) < receiverObserved.size() &&
            static_cast<std::size_t>(col) < senderObserved.size() &&
            receiverObserved[static_cast<std::size_t>(row)] &&
            senderObserved[static_cast<std::size_t>(col)]);
  };

  constexpr double kEps = 1e-12;
  if (groundTruthAvailable) {
    if (groundTruth.rows() != static_cast<int>(dataset.numObjects) ||
        groundTruth.cols() != static_cast<int>(dataset.numObjects)) {
      return 0.0;
    }
    double mass = 0.0;
    for (int row = 0; row < groundTruth.rows(); ++row) {
      for (int col = 0; col < groundTruth.cols(); ++col) {
        const double value = groundTruth(row, col);
        if (isEligible(row, col) && std::isfinite(value) && value > kEps) {
          mass += value;
        }
      }
    }
    return mass;
  }

  double diagonalMass = 0.0;
  const int diagonalCount = std::min(
      static_cast<int>(dataset.numObjects),
      static_cast<int>(groundTruth.rows()));
  for (int index = 0; index < diagonalCount; ++index) {
    if (index < groundTruth.cols() && isEligible(index, index)) {
      diagonalMass += 1.0;
    }
  }
  return diagonalMass;
}

DirectedAssociationScalars makeAssociationRecallDenominators(
    const ObjectPGODirectoryData &dataset,
    const ManualObjectDranOptions &options,
    const DirectedAssociationWeights &groundTruthAssociationWeights,
    bool groundTruthAvailable) {
  DirectedAssociationScalars denominators =
      makeZeroDirectedAssociationScalars(dataset.numRobots);
  for (std::size_t receiverId = 0; receiverId < dataset.numRobots;
       ++receiverId) {
    for (std::size_t senderId = 0; senderId < dataset.numRobots; ++senderId) {
      if (receiverId >= groundTruthAssociationWeights.size() ||
          senderId >= groundTruthAssociationWeights[receiverId].size()) {
        continue;
      }
      denominators[receiverId][senderId] =
          associationRecallDenominatorForPair(
              dataset, receiverId, senderId, options,
              groundTruthAssociationWeights[receiverId][senderId],
              groundTruthAvailable);
    }
  }
  return denominators;
}

std::vector<std::vector<double>> objectObservationInformationScales(
    const ObjectPGODirectoryData &dataset, unsigned d) {
  std::vector<std::vector<double>> information(
      dataset.numRobots, std::vector<double>(dataset.numObjects, 0.0));
  double positiveSum = 0.0;
  std::size_t positiveCount = 0;
  for (std::size_t robotId = 0; robotId < dataset.numRobots; ++robotId) {
    for (const ObjectObservationMeasurement &obs :
         dataset.robots[robotId].objectObservationMeasurements) {
      if (obs.objectGlobalVertexId >= dataset.numObjects) {
        continue;
      }
      const double kappa = std::isfinite(obs.measurement.kappa)
                               ? std::max(0.0, obs.measurement.kappa)
                               : 0.0;
      const double tau = std::isfinite(obs.measurement.tau)
                             ? std::max(0.0, obs.measurement.tau)
                             : 0.0;
      information[robotId][obs.objectGlobalVertexId] +=
          static_cast<double>(d) * (kappa + tau);
    }
  }
  for (const std::vector<double> &robotInformation : information) {
    for (double value : robotInformation) {
      if (value > 0.0) {
        positiveSum += value;
        ++positiveCount;
      }
    }
  }
  if (positiveCount == 0 || positiveSum <= 0.0) {
    for (std::vector<double> &robotScales : information) {
      std::fill(robotScales.begin(), robotScales.end(), 1.0);
    }
    return information;
  }
  const double meanInformation =
      positiveSum / static_cast<double>(positiveCount);
  for (std::vector<double> &robotScales : information) {
    for (double &value : robotScales) {
      value = value > 0.0 ? value / meanInformation : 1.0;
    }
  }
  return information;
}

bool associationObjectObservationUncertaintyEnabled(
    const ManualObjectDranOptions &options) {
  return (std::isfinite(
              options.associationObjectObservationUncertaintyCountPrior) &&
          options.associationObjectObservationUncertaintyCountPrior > 0.0) ||
         (std::isfinite(
              options.associationObjectObservationUncertaintyDistanceScale) &&
          options.associationObjectObservationUncertaintyDistanceScale > 0.0);
}

std::vector<double> objectObservationUncertaintyScales(
    const ObjectPGODirectoryData &dataset, std::size_t robotId,
    const ManualObjectDranOptions &options) {
  std::vector<std::size_t> counts(dataset.numObjects, 0u);
  std::vector<double> distanceSums(dataset.numObjects, 0.0);
  if (robotId >= dataset.robots.size()) {
    return std::vector<double>(dataset.numObjects, 1.0);
  }
  for (const ObjectObservationMeasurement &obs :
       dataset.robots[robotId].objectObservationMeasurements) {
    if (obs.objectGlobalVertexId >= dataset.numObjects) {
      continue;
    }
    ++counts[obs.objectGlobalVertexId];
    const double distance =
        obs.measurement.t.size() > 0 ? obs.measurement.t.norm() : 0.0;
    if (std::isfinite(distance)) {
      distanceSums[obs.objectGlobalVertexId] += std::max(0.0, distance);
    }
  }
  std::vector<double> scales(dataset.numObjects, 1.0);
  for (std::size_t objectId = 0; objectId < dataset.numObjects; ++objectId) {
    const double meanDistance =
        counts[objectId] > 0
            ? distanceSums[objectId] / static_cast<double>(counts[objectId])
            : std::numeric_limits<double>::infinity();
    scales[objectId] = objectObservationUncertaintyReliability(
        counts[objectId], meanDistance,
        options.associationObjectObservationUncertaintyCountPrior,
        options.associationObjectObservationUncertaintyDistanceScale,
        options.associationObjectObservationUncertaintyMinReliability);
  }
  if (options.associationObjectObservationUncertaintyNormalizeInformation) {
    double scaleSum = 0.0;
    std::size_t scaleCount = 0;
    for (std::size_t objectId = 0; objectId < dataset.numObjects; ++objectId) {
      if (counts[objectId] == 0 || !std::isfinite(scales[objectId]) ||
          scales[objectId] <= 0.0) {
        continue;
      }
      scaleSum += scales[objectId];
      ++scaleCount;
    }
    if (scaleCount > 0 && scaleSum > 0.0) {
      const double meanScale = scaleSum / static_cast<double>(scaleCount);
      for (std::size_t objectId = 0; objectId < dataset.numObjects;
           ++objectId) {
        if (counts[objectId] > 0 && std::isfinite(scales[objectId]) &&
            scales[objectId] > 0.0) {
          scales[objectId] /= meanScale;
        }
      }
    }
  }
  return scales;
}

std::size_t countObservedObjectCopies(const ObjectPGODirectoryData &dataset) {
  std::size_t count = 0;
  for (const ObjectPGORobotData &robot : dataset.robots) {
    const std::vector<bool> observed =
        observedObjects(robot, dataset.numObjects);
    count += static_cast<std::size_t>(
        std::count(observed.begin(), observed.end(), true));
  }
  return count;
}

Matrix blockPose(const Matrix &state, std::size_t poseIndex, unsigned d) {
  return state.block(0, poseIndex * (d + 1), d, d + 1);
}

Matrix identityPoseBlock(unsigned d) {
  Matrix pose = Matrix::Zero(d, d + 1);
  pose.leftCols(d).setIdentity();
  return pose;
}

Matrix composePoseBlocks(const Matrix &left, const Matrix &right, unsigned d) {
  Matrix pose = Matrix::Zero(d, d + 1);
  pose.leftCols(d) = left.leftCols(d) * right.leftCols(d);
  pose.rightCols(1) =
      left.rightCols(1) + left.leftCols(d) * right.rightCols(1);
  return pose;
}

Matrix inversePoseBlock(const Matrix &pose, unsigned d) {
  Matrix inverse = Matrix::Zero(d, d + 1);
  inverse.leftCols(d) = pose.leftCols(d).transpose();
  inverse.rightCols(1) = -inverse.leftCols(d) * pose.rightCols(1);
  return inverse;
}

bool isValidPoseBlock(const Matrix &pose, unsigned d) {
  return pose.rows() == static_cast<int>(d) &&
         pose.cols() == static_cast<int>(d + 1) && pose.allFinite();
}

void setPoseBlock(Matrix &state, std::size_t poseIndex, const Matrix &pose,
                  unsigned d) {
  state.block(0, poseIndex * (d + 1), d, d + 1) = pose;
}

Matrix projectStateToSE(const Matrix &state, unsigned d) {
  Matrix projected = state;
  if (projected.rows() != static_cast<int>(d) || d == 0) {
    return projected;
  }
  const unsigned blockWidth = d + 1;
  const std::size_t numPoses =
      static_cast<std::size_t>(projected.cols()) / blockWidth;
  for (std::size_t poseId = 0; poseId < numPoses; ++poseId) {
    projected.block(0, poseId * blockWidth, d, d) =
        projectToRotationGroup(
            projected.block(0, poseId * blockWidth, d, d));
  }
  return projected;
}

std::vector<Matrix> projectStatesToSE(const std::vector<Matrix> &states,
                                      unsigned d) {
  std::vector<Matrix> projected;
  projected.reserve(states.size());
  for (const Matrix &state : states) {
    projected.push_back(projectStateToSE(state, d));
  }
  return projected;
}

Matrix assembleObjectAwareInputState(const ObjectPGODirectoryData &dataset,
                                     std::size_t robotId, unsigned d) {
  const ObjectPGORobotData &robot = dataset.robots[robotId];
  const std::size_t localNumPoses =
      robot.trajectoryVertexIds.size() + dataset.numObjects;
  Matrix state = Matrix::Zero(d, localNumPoses * (d + 1));
  for (std::size_t localIdx = 0; localIdx < robot.trajectoryVertexIds.size();
       ++localIdx) {
    const Matrix pose =
        localIdx < robot.trajectoryInitialPoses.size()
            ? robot.trajectoryInitialPoses[localIdx]
            : Matrix();
    setPoseBlock(state, localIdx,
                 isValidPoseBlock(pose, d) ? pose : identityPoseBlock(d), d);
  }
  for (std::size_t objectId = 0; objectId < dataset.numObjects; ++objectId) {
    const std::size_t localIdx = robot.trajectoryVertexIds.size() + objectId;
    const Matrix pose =
        objectId < robot.objectInitialPoses.size()
            ? robot.objectInitialPoses[objectId]
            : Matrix();
    setPoseBlock(state, localIdx,
                 isValidPoseBlock(pose, d) ? pose : identityPoseBlock(d), d);
  }
  return state;
}

std::vector<Matrix> localObjectAwareChordalStates(
    const ObjectPGODirectoryData &dataset, unsigned d) {
  std::vector<Matrix> states;
  states.reserve(dataset.robots.size());
  for (const ObjectPGORobotData &robot : dataset.robots) {
    const std::size_t localNumPoses =
        robot.trajectoryVertexIds.size() + dataset.numObjects;
    Matrix state = assembleObjectAwareInputState(dataset, robot.robotId, d);
    const std::vector<RelativeSEMeasurement> measurements =
        objectAwareLocalMeasurements(robot);
    if (!measurements.empty()) {
      std::vector<int> localToCompact(localNumPoses, -1);
      std::vector<std::size_t> compactToLocal;
      auto compactIndex = [&](std::size_t localIdx) {
        if (localIdx >= localToCompact.size()) {
          throw std::runtime_error(
              "Object-aware local measurement index is out of range");
        }
        int &index = localToCompact[localIdx];
        if (index < 0) {
          index = static_cast<int>(compactToLocal.size());
          compactToLocal.push_back(localIdx);
        }
        return static_cast<std::size_t>(index);
      };

      std::vector<RelativeSEMeasurement> compactMeasurements;
      compactMeasurements.reserve(measurements.size());
      for (RelativeSEMeasurement m : measurements) {
        m.p1 = compactIndex(m.p1);
        m.p2 = compactIndex(m.p2);
        compactMeasurements.push_back(std::move(m));
      }

      const Matrix chordal =
          chordalInitialization(d, compactToLocal.size(), compactMeasurements);
      Matrix gauge = identityPoseBlock(d);
      if (!compactToLocal.empty()) {
        const Matrix inputAnchor = blockPose(state, compactToLocal.front(), d);
        const Matrix chordalAnchor = blockPose(chordal, 0, d);
        if (isValidPoseBlock(inputAnchor, d) &&
            isValidPoseBlock(chordalAnchor, d)) {
          gauge = composePoseBlocks(inputAnchor,
                                    inversePoseBlock(chordalAnchor, d), d);
        }
      }
      for (std::size_t compactIdx = 0; compactIdx < compactToLocal.size();
           ++compactIdx) {
        const Matrix pose =
            composePoseBlocks(gauge, blockPose(chordal, compactIdx, d), d);
        if (isValidPoseBlock(pose, d)) {
          setPoseBlock(state, compactToLocal[compactIdx], pose, d);
        }
      }
    }
    states.push_back(projectStateToSE(state, d));
  }
  return states;
}

ObjectInitializationResult initializeObjectStates(
    const ObjectPGODirectoryData &dataset, unsigned d,
    const NeighborRound &initializationNeighbors,
    const ManualObjectDranOptions &options) {
  ObjectInitializationResult result;
  result.observedObjectCopies = countObservedObjectCopies(dataset);
  result.relayOnlyObjectCopies =
      dataset.numRobots * dataset.numObjects - result.observedObjectCopies;
  if (options.objectInitialization ==
      ManualObjectDranObjectInitialization::InputState) {
    result.states.reserve(dataset.robots.size());
    for (const ObjectPGORobotData &robot : dataset.robots) {
      result.states.push_back(projectStateToSE(
          assembleObjectAwareInputState(dataset, robot.robotId, d), d));
    }
    return result;
  }
  if (options.objectInitialization ==
      ManualObjectDranObjectInitialization::CentralizedChordal) {
    result.states =
        projectStatesToSE(centralizedObjectAwareChordalStates(dataset, d), d);
    return result;
  }

  result.states = localObjectAwareChordalStates(dataset, d);
  std::vector<std::vector<bool>> initialized(
      dataset.numRobots, std::vector<bool>(dataset.numObjects, false));
  std::vector<std::vector<bool>> initializedFromNeighbor(
      dataset.numRobots, std::vector<bool>(dataset.numObjects, false));
  for (std::size_t robotId = 0; robotId < dataset.numRobots; ++robotId) {
    initialized[robotId] = observedObjects(dataset.robots[robotId],
                                           dataset.numObjects);
  }
  const std::vector<std::vector<bool>> observedByRobot = initialized;

  for (std::size_t pass = 0; pass < dataset.numRobots; ++pass) {
    bool changed = false;
    std::vector<Matrix> nextStates = result.states;
    std::vector<std::vector<bool>> nextInitialized = initialized;
    for (std::size_t robotId = 0; robotId < dataset.numRobots; ++robotId) {
      const ObjectPGORobotData &robot = dataset.robots[robotId];
      const std::size_t objectOffset = robot.trajectoryVertexIds.size();
      for (std::size_t objectId = 0; objectId < dataset.numObjects;
           ++objectId) {
        if (initialized[robotId][objectId]) {
          continue;
        }
        Matrix rotationSum = Matrix::Zero(d, d);
        Matrix translationSum = Matrix::Zero(d, 1);
        double weightSum = 0.0;
        for (const WeightedNeighbor &neighbor :
             initializationNeighbors[robotId]) {
          if (!initialized[neighbor.id][objectId]) {
            continue;
          }
          const ObjectPGORobotData &neighborRobot =
              dataset.robots[neighbor.id];
          const std::size_t neighborObjectIndex =
              neighborRobot.trajectoryVertexIds.size() + objectId;
          const Matrix neighborPose =
              blockPose(result.states[neighbor.id], neighborObjectIndex, d);
          rotationSum.noalias() +=
              neighbor.weight * neighborPose.leftCols(d);
          translationSum.noalias() +=
              neighbor.weight * neighborPose.rightCols(1);
          weightSum += neighbor.weight;
        }
        if (weightSum <= 0.0) {
          continue;
        }
        Matrix averaged = Matrix::Zero(d, d + 1);
        averaged.leftCols(d) = projectToRotationGroup(rotationSum);
        averaged.rightCols(1) = translationSum / weightSum;
        setPoseBlock(nextStates[robotId], objectOffset + objectId, averaged,
                     d);
        nextInitialized[robotId][objectId] = true;
        initializedFromNeighbor[robotId][objectId] = true;
        changed = true;
      }
    }
    result.states = projectStatesToSE(nextStates, d);
    initialized = std::move(nextInitialized);
    if (!changed) {
      break;
    }
  }

  const std::size_t consensusRounds =
      options.objectInitializationConsensusRounds;
  const double observedAnchorWeight =
      std::isfinite(options.objectInitializationObservedAnchorWeight)
          ? std::max(0.0, options.objectInitializationObservedAnchorWeight)
          : 0.0;
  const double relayAnchorWeight =
      std::isfinite(options.objectInitializationRelayAnchorWeight)
          ? std::max(0.0, options.objectInitializationRelayAnchorWeight)
          : 0.0;
  if (consensusRounds > 0 &&
      (observedAnchorWeight > 0.0 || relayAnchorWeight > 0.0 ||
       !initializationNeighbors.empty())) {
    const std::vector<Matrix> anchorStates = result.states;
    const bool useInformationAnchors =
        options.objectInitializationAnchorMode ==
        ManualObjectDranObjectInitializationAnchorMode::Information;
    const std::vector<std::vector<double>> anchorScales =
        useInformationAnchors
            ? objectObservationInformationScales(dataset, d)
            : std::vector<std::vector<double>>();
    for (std::size_t round = 0; round < consensusRounds; ++round) {
      std::vector<Matrix> nextStates = result.states;
      for (std::size_t robotId = 0; robotId < dataset.numRobots; ++robotId) {
        const ObjectPGORobotData &robot = dataset.robots[robotId];
        const std::size_t objectOffset = robot.trajectoryVertexIds.size();
        for (std::size_t objectId = 0; objectId < dataset.numObjects;
             ++objectId) {
          if (!initialized[robotId][objectId]) {
            continue;
          }
          Matrix rotationSum = Matrix::Zero(d, d);
          Matrix translationSum = Matrix::Zero(d, 1);
          double weightSum = 0.0;
          const std::size_t localObjectIndex = objectOffset + objectId;
          double anchorWeight =
              observedByRobot[robotId][objectId] ? observedAnchorWeight
                                                 : relayAnchorWeight;
          if (useInformationAnchors && observedByRobot[robotId][objectId]) {
            anchorWeight *= anchorScales[robotId][objectId];
          }
          if (anchorWeight > 0.0) {
            const Matrix anchor =
                blockPose(anchorStates[robotId], localObjectIndex, d);
            rotationSum.noalias() += anchorWeight * anchor.leftCols(d);
            translationSum.noalias() += anchorWeight * anchor.rightCols(1);
            weightSum += anchorWeight;
          }
          for (const WeightedNeighbor &neighbor :
               initializationNeighbors[robotId]) {
            if (!initialized[neighbor.id][objectId]) {
              continue;
            }
            const ObjectPGORobotData &neighborRobot =
                dataset.robots[neighbor.id];
            const std::size_t neighborObjectIndex =
                neighborRobot.trajectoryVertexIds.size() + objectId;
            const Matrix neighborPose =
                blockPose(result.states[neighbor.id], neighborObjectIndex, d);
            rotationSum.noalias() +=
                neighbor.weight * neighborPose.leftCols(d);
            translationSum.noalias() +=
                neighbor.weight * neighborPose.rightCols(1);
            weightSum += neighbor.weight;
          }
          if (weightSum <= 0.0) {
            continue;
          }
          Matrix averaged = Matrix::Zero(d, d + 1);
          averaged.leftCols(d) = projectToRotationGroup(rotationSum);
          averaged.rightCols(1) = translationSum / weightSum;
          setPoseBlock(nextStates[robotId], localObjectIndex, averaged, d);
        }
      }
      result.states = projectStatesToSE(nextStates, d);
    }
  }

  for (std::size_t robotId = 0; robotId < dataset.numRobots; ++robotId) {
    for (std::size_t objectId = 0; objectId < dataset.numObjects; ++objectId) {
      if (initializedFromNeighbor[robotId][objectId]) {
        ++result.initializedFromNeighborObjectCopies;
      }
      if (!initialized[robotId][objectId]) {
        ++result.staleObjectCopies;
      }
    }
  }
  return result;
}

double measurementCost(const RelativeSEMeasurement &m, const Matrix &state,
                       unsigned d) {
  const Matrix pose1 = blockPose(state, m.p1, d);
  const Matrix pose2 = blockPose(state, m.p2, d);
  const Matrix R1 = pose1.leftCols(d);
  const Matrix R2 = pose2.leftCols(d);
  const Matrix t1 = pose1.rightCols(1);
  const Matrix t2 = pose2.rightCols(1);
  return m.kappa * (R1 * m.R - R2).squaredNorm() +
         m.tau * (t2 - t1 - R1 * m.t).squaredNorm();
}

std::vector<double> objectObservationFactorCosts(
    const ObjectPGORobotData &robot, const Matrix &state,
    std::size_t numObjects, unsigned d) {
  std::vector<double> costs(numObjects, 0.0);
  for (const ObjectObservationMeasurement &observation :
       robot.objectObservationMeasurements) {
    if (observation.objectGlobalVertexId >= numObjects) {
      continue;
    }
    costs[observation.objectGlobalVertexId] +=
        measurementCost(observation.measurement, state, d);
  }
  return costs;
}

double objectMeasurementResidualNorm(const ObjectPGORobotData &robot,
                                     const Matrix &state,
                                     std::size_t objectId, unsigned d) {
  double residualSquared = 0.0;
  for (const ObjectObservationMeasurement &obs :
       robot.objectObservationMeasurements) {
    if (obs.objectGlobalVertexId != objectId) {
      continue;
    }
    residualSquared += measurementCost(obs.measurement, state, d);
  }
  return std::sqrt(residualSquared);
}

double objectMeasurementResidualNormForPose(
    const ObjectPGORobotData &robot, const Matrix &state,
    std::size_t objectId, const Matrix &objectPose, unsigned d) {
  if (d == 0 || objectPose.rows() != static_cast<int>(d) ||
      objectPose.cols() != static_cast<int>(d + 1) ||
      !objectPose.allFinite()) {
    return std::numeric_limits<double>::infinity();
  }
  double residualSquared = 0.0;
  bool observed = false;
  for (const ObjectObservationMeasurement &obs :
       robot.objectObservationMeasurements) {
    if (obs.objectGlobalVertexId != objectId ||
        obs.trajectoryLocalIndex >= robot.trajectoryVertexIds.size() ||
        obs.measurement.R.rows() != static_cast<int>(d) ||
        obs.measurement.R.cols() < static_cast<int>(d) ||
        obs.measurement.t.rows() < static_cast<int>(d)) {
      continue;
    }
    const Matrix trajectoryPose =
        blockPose(state, obs.trajectoryLocalIndex, d);
    const Matrix predictedRotation =
        trajectoryPose.leftCols(static_cast<int>(d)) *
        obs.measurement.R.leftCols(static_cast<int>(d));
    const Vector predictedTranslation =
        trajectoryPose.col(static_cast<int>(d)) +
        trajectoryPose.leftCols(static_cast<int>(d)) *
            obs.measurement.t.topRows(static_cast<int>(d));
    residualSquared +=
        obs.measurement.kappa *
            (predictedRotation -
             objectPose.leftCols(static_cast<int>(d)))
                .squaredNorm() +
        obs.measurement.tau *
            (objectPose.col(static_cast<int>(d)) -
             predictedTranslation)
                .squaredNorm();
    observed = true;
  }
  return observed ? std::sqrt(residualSquared)
                  : std::numeric_limits<double>::infinity();
}

double objectLeaveOneOutObservationPredictiveCost(
    const ObjectPGORobotData &robot, const Matrix &state,
    std::size_t objectId, unsigned d) {
  if (d == 0 || state.rows() != static_cast<int>(d)) {
    return std::numeric_limits<double>::quiet_NaN();
  }
  std::vector<const ObjectObservationMeasurement *> observations;
  for (const ObjectObservationMeasurement &observation :
       robot.objectObservationMeasurements) {
    if (observation.objectGlobalVertexId == objectId &&
        observation.trajectoryLocalIndex < robot.trajectoryVertexIds.size()) {
      observations.push_back(&observation);
    }
  }
  if (observations.size() < 2u) {
    return std::numeric_limits<double>::quiet_NaN();
  }

  std::vector<Matrix> impliedPoses;
  impliedPoses.reserve(observations.size());
  Matrix rotationSum = Matrix::Zero(d, d);
  Vector translationSum = Vector::Zero(d);
  std::size_t validCount = 0u;
  for (const ObjectObservationMeasurement *observation : observations) {
    Matrix implied =
        objectObservationImpliedPose(state, *observation, d);
    if (implied.rows() != static_cast<int>(d) ||
        implied.cols() != static_cast<int>(d + 1u) ||
        !implied.allFinite()) {
      impliedPoses.emplace_back();
      continue;
    }
    rotationSum.noalias() += implied.leftCols(static_cast<int>(d));
    translationSum.noalias() += implied.col(static_cast<int>(d));
    ++validCount;
    impliedPoses.push_back(std::move(implied));
  }
  if (validCount < 2u) {
    return std::numeric_limits<double>::quiet_NaN();
  }

  double cost = 0.0;
  std::size_t evaluatedCount = 0u;
  const double leaveOneOutCount = static_cast<double>(validCount - 1u);
  for (std::size_t index = 0; index < observations.size(); ++index) {
    const Matrix &implied = impliedPoses[index];
    if (implied.rows() != static_cast<int>(d) ||
        implied.cols() != static_cast<int>(d + 1u) ||
        !implied.allFinite()) {
      continue;
    }
    const Matrix meanRotation = projectToRotationGroup(
        rotationSum - implied.leftCols(static_cast<int>(d)));
    const Vector meanTranslation =
        (translationSum - implied.col(static_cast<int>(d))) /
        leaveOneOutCount;
    const RelativeSEMeasurement &measurement =
        observations[index]->measurement;
    cost += measurement.kappa *
                (implied.leftCols(static_cast<int>(d)) - meanRotation)
                    .squaredNorm() +
            measurement.tau *
                (implied.col(static_cast<int>(d)) - meanTranslation)
                    .squaredNorm();
    ++evaluatedCount;
  }
  return evaluatedCount >= 2u
             ? cost
             : std::numeric_limits<double>::quiet_NaN();
}

double totalMeasurementCost(
    const std::vector<std::vector<RelativeSEMeasurement>> &measurements,
    const std::vector<Matrix> &states, unsigned d) {
  double cost = 0.0;
  for (std::size_t robotId = 0; robotId < states.size(); ++robotId) {
    for (const RelativeSEMeasurement &m : measurements[robotId]) {
      cost += measurementCost(m, states[robotId], d);
    }
  }
  return cost;
}

double localObjectAwareMeasurementCost(
    const ObjectPGORobotData &robot, const Matrix &state,
    const ManualObjectDranOptions &options, unsigned d) {
  const bool heldoutSplitActive = primaryLowerHeldoutSplitEnabled(&options);
  const std::vector<RelativeSEMeasurement> measurements =
      objectAwareLocalMeasurements(robot, &state, d, &options,
                                   heldoutSplitActive
                                       ? LocalMeasurementSubset::Train
                                       : LocalMeasurementSubset::All);
  double cost = 0.0;
  for (const RelativeSEMeasurement &measurement : measurements) {
    cost += measurementCost(measurement, state, d);
  }
  return cost;
}

double measurementIncumbentProxBlend(double currentCost, double incumbentCost) {
  if (!std::isfinite(currentCost) || !std::isfinite(incumbentCost) ||
      currentCost <= incumbentCost || incumbentCost < 0.0) {
    return 0.0;
  }
  const double denominator = std::max(incumbentCost, 1.0);
  const double relativeExcess =
      std::max(0.0, (currentCost - incumbentCost) / denominator);
  const double rootExcess = std::sqrt(relativeExcess);
  return std::clamp(rootExcess / (1.0 + rootExcess), 0.0, 1.0);
}

void blendStateTranslationsToward(Matrix &state, const Matrix &reference,
                                  double alpha, unsigned d) {
  if (!std::isfinite(alpha) || alpha <= 0.0 ||
      state.rows() != reference.rows() || state.cols() != reference.cols() ||
      state.cols() == 0) {
    return;
  }
  alpha = std::clamp(alpha, 0.0, 1.0);
  const unsigned blockWidth = d + 1;
  const std::size_t numBlocks =
      static_cast<std::size_t>(state.cols()) / blockWidth;
  for (std::size_t blockId = 0; blockId < numBlocks; ++blockId) {
    const int col = static_cast<int>(blockId * blockWidth + d);
    state.col(col) =
        (1.0 - alpha) * state.col(col) + alpha * reference.col(col);
  }
}

void blendReceiverAssociationWeightsToward(
    DirectedAssociationWeights &weights, const DirectedAssociationWeights &reference,
    std::size_t receiverId, double alpha) {
  if (!std::isfinite(alpha) || alpha <= 0.0 || receiverId >= weights.size() ||
      receiverId >= reference.size()) {
    return;
  }
  alpha = std::clamp(alpha, 0.0, 1.0);
  for (std::size_t senderId = 0;
       senderId < weights[receiverId].size() &&
       senderId < reference[receiverId].size();
       ++senderId) {
    Matrix &current = weights[receiverId][senderId];
    const Matrix &incumbent = reference[receiverId][senderId];
    if (current.rows() == incumbent.rows() &&
        current.cols() == incumbent.cols() && current.size() > 0) {
      current = (1.0 - alpha) * current + alpha * incumbent;
    }
  }
}

double totalLeaveOneOutObjectObservationPredictiveCost(
    const ObjectPGODirectoryData &dataset, const std::vector<Matrix> &states,
    unsigned d) {
  double cost = 0.0;
  for (std::size_t robotId = 0; robotId < dataset.robots.size(); ++robotId) {
    if (robotId >= states.size()) {
      continue;
    }
    const ObjectPGORobotData &robot = dataset.robots[robotId];
    std::vector<std::vector<const ObjectObservationMeasurement *>> byObject(
        dataset.numObjects);
    for (const ObjectObservationMeasurement &obs :
         robot.objectObservationMeasurements) {
      if (obs.objectGlobalVertexId >= dataset.numObjects ||
          obs.trajectoryLocalIndex >= robot.trajectoryVertexIds.size()) {
        continue;
      }
      byObject[obs.objectGlobalVertexId].push_back(&obs);
    }
    for (const std::vector<const ObjectObservationMeasurement *> &observations :
         byObject) {
      if (observations.size() < 2) {
        continue;
      }
      std::vector<Matrix> impliedPoses;
      impliedPoses.reserve(observations.size());
      Matrix rotationSum = Matrix::Zero(d, d);
      Vector translationSum = Vector::Zero(d);
      std::size_t validCount = 0;
      for (const ObjectObservationMeasurement *obs : observations) {
        Matrix implied = objectObservationImpliedPose(states[robotId], *obs, d);
        if (implied.rows() != static_cast<int>(d) ||
            implied.cols() != static_cast<int>(d + 1) ||
            !implied.allFinite()) {
          impliedPoses.emplace_back();
          continue;
        }
        rotationSum.noalias() += implied.leftCols(static_cast<int>(d));
        translationSum.noalias() += implied.col(static_cast<int>(d));
        ++validCount;
        impliedPoses.push_back(std::move(implied));
      }
      if (validCount < 2) {
        continue;
      }
      for (std::size_t obsIndex = 0; obsIndex < observations.size();
           ++obsIndex) {
        const Matrix &implied = impliedPoses[obsIndex];
        if (implied.rows() != static_cast<int>(d) ||
            implied.cols() != static_cast<int>(d + 1) ||
            !implied.allFinite()) {
          continue;
        }
        const double leaveOneOutCount =
            static_cast<double>(validCount - 1u);
        if (leaveOneOutCount <= 0.0) {
          continue;
        }
        const Matrix meanRotation = projectToRotationGroup(
            rotationSum - implied.leftCols(static_cast<int>(d)));
        const Vector meanTranslation =
            (translationSum - implied.col(static_cast<int>(d))) /
            leaveOneOutCount;
        const RelativeSEMeasurement &measurement =
            observations[obsIndex]->measurement;
        cost += measurement.kappa *
                    (implied.leftCols(static_cast<int>(d)) - meanRotation)
                        .squaredNorm() +
                measurement.tau *
                    (implied.col(static_cast<int>(d)) - meanTranslation)
                        .squaredNorm();
      }
    }
  }
  return cost;
}

double syntheticMetadataAssociationCost(
    const SyntheticObjectMetadataSet *metadata, std::size_t robotId,
    std::size_t targetRobotId, std::size_t localObjectId,
    std::size_t targetObjectId, const ManualObjectDranOptions &options) {
  if (!metadata || !options.associationUseSyntheticMetadata ||
      robotId >= metadata->observations.size() ||
      targetRobotId >= metadata->observations.size() ||
      localObjectId >= metadata->observations[robotId].size() ||
      targetObjectId >= metadata->observations[targetRobotId].size()) {
    return 0.0;
  }
  const SyntheticObjectObservationMetadata &local =
      metadata->observations[robotId][localObjectId];
  const SyntheticObjectObservationMetadata &target =
      metadata->observations[targetRobotId][targetObjectId];
  double cost = semanticAssociationMismatchLowerBoundCost(
      local.category, local.semanticConfidence, target.category,
      target.semanticConfidence, options);
  if (options.associationShapeWeight > 0.0 &&
      local.shape.rows() == target.shape.rows()) {
    cost += options.associationShapeWeight *
            (local.shape - target.shape).squaredNorm();
  }
  if (options.associationDescriptorWeight > 0.0 &&
      local.descriptor.rows() == target.descriptor.rows() &&
      local.descriptor.norm() > 1e-12 &&
      target.descriptor.norm() > 1e-12) {
    const double dot = local.descriptor.dot(target.descriptor);
    const double cosineDistance = 1.0 - std::max(-1.0, std::min(1.0, dot));
    cost += options.associationDescriptorWeight * cosineDistance;
  }
  return cost;
}

bool hasSyntheticObservationMetadata(
    const SyntheticObjectMetadataSet *metadata, std::size_t robotId,
    std::size_t targetRobotId, std::size_t localObjectId,
    std::size_t targetObjectId, const ManualObjectDranOptions &options) {
  return metadata && options.associationUseSyntheticMetadata &&
         robotId < metadata->observations.size() &&
         targetRobotId < metadata->observations.size() &&
         localObjectId < metadata->observations[robotId].size() &&
         targetObjectId < metadata->observations[targetRobotId].size();
}

void applyObservedAssociationMask(const ObjectPGODirectoryData &dataset,
                                  std::size_t robotId,
                                  std::size_t targetRobotId,
                                  const ManualObjectDranOptions &options,
                                  Matrix &costs) {
  if (!options.associationRequireObservedObjects) {
    return;
  }
  const std::vector<bool> localObserved =
      observedObjects(dataset.robots[robotId], dataset.numObjects);
  const std::vector<bool> targetObserved =
      observedObjects(dataset.robots[targetRobotId], dataset.numObjects);
  const double invalidCost = std::numeric_limits<double>::infinity();
  for (std::size_t localObjectId = 0; localObjectId < dataset.numObjects;
       ++localObjectId) {
    for (std::size_t targetObjectId = 0; targetObjectId < dataset.numObjects;
         ++targetObjectId) {
      if (!localObserved[localObjectId] || !targetObserved[targetObjectId]) {
        costs(static_cast<int>(localObjectId),
              static_cast<int>(targetObjectId)) = invalidCost;
      }
    }
  }
}

void applyObservedAssociationWeightMask(
    const ObjectPGODirectoryData &dataset, std::size_t robotId,
    std::size_t targetRobotId, const ManualObjectDranOptions &options,
    Matrix &weights) {
  if (!options.associationRequireObservedObjects) {
    return;
  }
  const std::vector<bool> localObserved =
      observedObjects(dataset.robots[robotId], dataset.numObjects);
  const std::vector<bool> targetObserved =
      observedObjects(dataset.robots[targetRobotId], dataset.numObjects);
  for (std::size_t localObjectId = 0; localObjectId < dataset.numObjects;
       ++localObjectId) {
    for (std::size_t targetObjectId = 0; targetObjectId < dataset.numObjects;
         ++targetObjectId) {
      if (!localObserved[localObjectId] || !targetObserved[targetObjectId]) {
        weights(static_cast<int>(localObjectId),
                static_cast<int>(targetObjectId)) = 0.0;
      }
    }
  }
}

std::array<unsigned, 2> transformAssociationPlaneAxes(
    unsigned d, const ManualObjectDranOptions &options) {
  if (d < 2) {
    throw std::runtime_error(
        "TransformSoft association requires dimension >= 2");
  }
  if (d == 2) {
    return {0, 1};
  }
  const std::string axes = lowerAscii(trim(options.associationTransformPlaneAxes));
  if (axes.empty() || axes == "xy") {
    return {0, 1};
  }
  if (axes == "xz") {
    return {0, 2};
  }
  if (axes == "yz") {
    return {1, 2};
  }
  throw std::runtime_error("Unsupported association transform plane axes: " +
                           options.associationTransformPlaneAxes);
}

unsigned associationTransformDimension(
    unsigned d, const ManualObjectDranOptions &options) {
  if (options.associationTransformDimension == 0) {
    return d;
  }
  if (options.associationTransformDimension < 2 ||
      options.associationTransformDimension > d) {
    throw std::runtime_error(
        "associationTransformDimension must be 0 or in [2, d]");
  }
  if (options.associationTransformDimension != 2 &&
      options.associationTransformDimension != d) {
    throw std::runtime_error(
        "associationTransformDimension currently supports only 2 or full d");
  }
  return options.associationTransformDimension;
}

Vector associationTransformObjectPoint(
    const Matrix &state, std::size_t objectIndex, unsigned d,
    unsigned transformDimension, const std::array<unsigned, 2> &axes) {
  const Matrix center = blockPose(state, objectIndex, d).rightCols(1);
  if (transformDimension == d) {
    return center;
  }
  Vector projected(2);
  projected(0) = center(static_cast<int>(axes[0]), 0);
  projected(1) = center(static_cast<int>(axes[1]), 0);
  return projected;
}

Matrix stateAssociationTransformPointMatrix(
    const ObjectPGODirectoryData &dataset, const Matrix &state,
    std::size_t robotId, unsigned d, const ManualObjectDranOptions &options,
    unsigned transformDimension) {
  const ObjectPGORobotData &robot = dataset.robots[robotId];
  const std::size_t objectOffset = robot.trajectoryVertexIds.size();
  const std::array<unsigned, 2> axes =
      transformAssociationPlaneAxes(d, options);
  Matrix points(dataset.numObjects, transformDimension);
  for (std::size_t objectId = 0; objectId < dataset.numObjects; ++objectId) {
    points.row(static_cast<int>(objectId)) =
        associationTransformObjectPoint(
            state, objectOffset + objectId, d, transformDimension, axes)
            .transpose();
  }
  return points;
}

Matrix applyAssociationTransformToPose(
    const Matrix &pose, unsigned d, const std::array<unsigned, 2> &axes,
    const Matrix &transform) {
  if (transform.rows() == static_cast<int>(d) &&
      transform.cols() == static_cast<int>(d + 1)) {
    Matrix mapped = pose;
    const Matrix fullRotation = transform.leftCols(static_cast<int>(d));
    mapped.leftCols(static_cast<int>(d)).noalias() =
        fullRotation * pose.leftCols(static_cast<int>(d));
    mapped.col(static_cast<int>(d)).noalias() =
        fullRotation * pose.rightCols(1) + transform.col(static_cast<int>(d));
    return mapped;
  }
  if (transform.rows() != 2 || transform.cols() != 3) {
    return pose;
  }
  Matrix fullRotation = Matrix::Identity(d, d);
  fullRotation(static_cast<int>(axes[0]), static_cast<int>(axes[0])) =
      transform(0, 0);
  fullRotation(static_cast<int>(axes[0]), static_cast<int>(axes[1])) =
      transform(0, 1);
  fullRotation(static_cast<int>(axes[1]), static_cast<int>(axes[0])) =
      transform(1, 0);
  fullRotation(static_cast<int>(axes[1]), static_cast<int>(axes[1])) =
      transform(1, 1);

  Matrix mapped = pose;
  mapped.leftCols(static_cast<int>(d)).noalias() =
      fullRotation * pose.leftCols(static_cast<int>(d));
  Vector translation = pose.rightCols(1);
  Vector sourcePlane(2);
  sourcePlane(0) = translation(static_cast<int>(axes[0]));
  sourcePlane(1) = translation(static_cast<int>(axes[1]));
  const Vector plane = transform.leftCols(2) * sourcePlane + transform.col(2);
  translation(static_cast<int>(axes[0])) = plane(0);
  translation(static_cast<int>(axes[1])) = plane(1);
  mapped.col(static_cast<int>(d)) = translation;
  return mapped;
}

Matrix invertAssociationTransform(unsigned d, const std::array<unsigned, 2> &axes,
                                  const Matrix &transform) {
  if (transform.rows() == static_cast<int>(d) &&
      transform.cols() == static_cast<int>(d + 1)) {
    Matrix inverse = Matrix::Zero(d, d + 1);
    const Matrix rotation = transform.leftCols(static_cast<int>(d));
    const Matrix rotationT = rotation.transpose();
    inverse.leftCols(static_cast<int>(d)) = rotationT;
    inverse.col(static_cast<int>(d)).noalias() =
        -rotationT * transform.col(static_cast<int>(d));
    return inverse;
  }
  if (transform.rows() == 2 && transform.cols() == 3) {
    Matrix inverse = Matrix::Zero(2, 3);
    const Matrix rotation = transform.leftCols(2);
    const Matrix rotationT = rotation.transpose();
    inverse.leftCols(2) = rotationT;
    inverse.col(2).noalias() = -rotationT * transform.col(2);
    return inverse;
  }
  Matrix identity = Matrix::Zero(d, d + 1);
  identity.leftCols(static_cast<int>(d)).setIdentity();
  (void)axes;
  return identity;
}

Matrix associationTransformRotationMatrix(
    unsigned d, const std::array<unsigned, 2> &axes,
    const Matrix &transform) {
  if (transform.rows() == static_cast<int>(d) &&
      transform.cols() == static_cast<int>(d + 1)) {
    return transform.leftCols(static_cast<int>(d));
  }
  Matrix rotation = Matrix::Identity(d, d);
  if (transform.rows() == 2 && transform.cols() == 3) {
    rotation(static_cast<int>(axes[0]), static_cast<int>(axes[0])) =
        transform(0, 0);
    rotation(static_cast<int>(axes[0]), static_cast<int>(axes[1])) =
        transform(0, 1);
    rotation(static_cast<int>(axes[1]), static_cast<int>(axes[0])) =
        transform(1, 0);
    rotation(static_cast<int>(axes[1]), static_cast<int>(axes[1])) =
        transform(1, 1);
  }
  return rotation;
}

Matrix pullBackAssociationTransformPoseGradient(
    const Matrix &gradient, unsigned d, const std::array<unsigned, 2> &axes,
    const Matrix &transform) {
  if (gradient.rows() != static_cast<int>(d) ||
      gradient.cols() != static_cast<int>(d + 1)) {
    return Matrix::Zero(d, d + 1);
  }
  const Matrix rotation =
      associationTransformRotationMatrix(d, axes, transform);
  Matrix pulled = Matrix::Zero(d, d + 1);
  pulled.leftCols(static_cast<int>(d)).noalias() =
      rotation.transpose() * gradient.leftCols(static_cast<int>(d));
  pulled.col(static_cast<int>(d)).noalias() =
      rotation.transpose() * gradient.col(static_cast<int>(d));
  return pulled;
}

TransformAssociationVerificationResult
transformSoftAssociationVerificationFromPoints(
    const ObjectPGODirectoryData &dataset, std::size_t robotId,
    std::size_t targetRobotId, unsigned d,
    const ManualObjectDranOptions &options,
    const SyntheticObjectMetadataSet *metadata, const Matrix &localPoints,
    const Matrix &targetPoints,
    const std::vector<ManualObjectDranAssociationCandidateEdge>
        *candidateEdges = nullptr) {
  const ObjectPGORobotData &robot = dataset.robots[robotId];
  const ObjectPGORobotData &targetRobot = dataset.robots[targetRobotId];
  const unsigned transformDimension =
      associationTransformDimension(d, options);
  const std::vector<bool> localObserved =
      observedObjects(robot, dataset.numObjects);
  const std::vector<bool> targetObserved =
      observedObjects(targetRobot, dataset.numObjects);

  std::vector<std::vector<std::size_t>> supportTargetIdsByRow;
  if (candidateEdges != nullptr) {
    supportTargetIdsByRow.resize(dataset.numObjects);
    for (const ManualObjectDranAssociationCandidateEdge &edge :
         *candidateEdges) {
      if (edge.row < dataset.numObjects && edge.col < dataset.numObjects) {
        supportTargetIdsByRow[edge.row].push_back(edge.col);
      }
    }
  }

  std::vector<std::size_t> observedTargetObjectIds;
  observedTargetObjectIds.reserve(dataset.numObjects);
  std::map<std::size_t, std::vector<std::size_t>> observedTargetIdsByCategory;
  for (std::size_t targetObjectId = 0; targetObjectId < dataset.numObjects;
       ++targetObjectId) {
    if (options.associationRequireObservedObjects &&
        !targetObserved[targetObjectId]) {
      continue;
    }
    observedTargetObjectIds.push_back(targetObjectId);
    if (metadata && options.associationUseSyntheticMetadata &&
        targetRobotId < metadata->observations.size() &&
        targetObjectId < metadata->observations[targetRobotId].size()) {
      const SyntheticObjectObservationMetadata &target =
          metadata->observations[targetRobotId][targetObjectId];
      observedTargetIdsByCategory[target.category].push_back(targetObjectId);
    }
  }

  std::vector<TransformAssociationCandidate> candidates;
  for (std::size_t localObjectId = 0; localObjectId < dataset.numObjects;
       ++localObjectId) {
    if (options.associationRequireObservedObjects &&
        !localObserved[localObjectId]) {
      continue;
    }
    std::vector<TransformAssociationCandidate> rowCandidates;
    const std::vector<std::size_t> *targetObjectIds =
        candidateEdges != nullptr ? &supportTargetIdsByRow[localObjectId]
                                  : &observedTargetObjectIds;
    const bool hasLocalMetadata =
        metadata && options.associationUseSyntheticMetadata &&
        robotId < metadata->observations.size() &&
        localObjectId < metadata->observations[robotId].size();
    if (candidateEdges == nullptr && hasLocalMetadata &&
        !observedTargetIdsByCategory.empty()) {
      const SyntheticObjectObservationMetadata &local =
          metadata->observations[robotId][localObjectId];
      bool allMismatchedTargetsCannotPass = true;
      for (const std::size_t targetObjectId : observedTargetObjectIds) {
        if (!hasSyntheticObservationMetadata(metadata, robotId, targetRobotId,
                                             localObjectId, targetObjectId,
                                             options)) {
          allMismatchedTargetsCannotPass = false;
          break;
        }
        const SyntheticObjectObservationMetadata &target =
            metadata->observations[targetRobotId][targetObjectId];
        if (target.category == local.category) {
          continue;
        }
        if (!semanticAssociationMismatchCannotPassMinScore(
                local.category, local.semanticConfidence, target.category,
                target.semanticConfidence, options)) {
          allMismatchedTargetsCannotPass = false;
          break;
        }
      }
      const auto categoryIt =
          observedTargetIdsByCategory.find(local.category);
      if (allMismatchedTargetsCannotPass &&
          categoryIt != observedTargetIdsByCategory.end()) {
        targetObjectIds = &categoryIt->second;
      } else if (allMismatchedTargetsCannotPass) {
        static const std::vector<std::size_t> emptyTargetObjectIds;
        targetObjectIds = &emptyTargetObjectIds;
      }
    }
    for (const std::size_t targetObjectId : *targetObjectIds) {
      if (hasSyntheticObservationMetadata(metadata, robotId, targetRobotId,
                                          localObjectId, targetObjectId,
                                          options)) {
        const SyntheticObjectObservationMetadata &local =
            metadata->observations[robotId][localObjectId];
        const SyntheticObjectObservationMetadata &target =
            metadata->observations[targetRobotId][targetObjectId];
        if (semanticAssociationMismatchCannotPassMinScore(
                local.category, local.semanticConfidence, target.category,
                target.semanticConfidence, options)) {
          continue;
        }
      }
      const double metadataCost = syntheticMetadataAssociationCost(
          metadata, robotId, targetRobotId, localObjectId, targetObjectId,
          options);
      if (!std::isfinite(metadataCost)) {
        continue;
      }
      const double score = std::exp(-std::max(0.0, metadataCost));
      if (score < options.associationTransformMinScore) {
        continue;
      }
      rowCandidates.push_back(TransformAssociationCandidate{
          localObjectId,
          targetObjectId,
          localPoints.row(static_cast<int>(localObjectId)).transpose(),
          targetPoints.row(static_cast<int>(targetObjectId)).transpose(),
          score});
    }
    std::sort(rowCandidates.begin(), rowCandidates.end(),
              [](const TransformAssociationCandidate &a,
                 const TransformAssociationCandidate &b) {
                if (a.score != b.score) {
                  return a.score > b.score;
                }
                return a.targetObjectId < b.targetObjectId;
              });
    if (options.associationMaxCandidatesPerEdge > 0 &&
        rowCandidates.size() > options.associationMaxCandidatesPerEdge) {
      rowCandidates.resize(options.associationMaxCandidatesPerEdge);
    }
    candidates.insert(candidates.end(), rowCandidates.begin(),
                      rowCandidates.end());
  }

  TransformAssociationVerificationOptions verifyOptions;
  verifyOptions.dimension = transformDimension;
  verifyOptions.minInliers = options.associationTransformMinInliers;
  verifyOptions.maxResidual = options.associationTransformMaxResidual;
  verifyOptions.minScore = options.associationTransformMinScore;
  verifyOptions.weightScale = options.associationTransformWeightScale;
  verifyOptions.maxSeedCandidates =
      options.associationTransformMaxSeedCandidates;
  return verifyTransformAwareAssociation(dataset.numObjects,
                                         dataset.numObjects, candidates,
                                         verifyOptions);
}

Matrix classOnlyAssociationCostMatrix(
    const ObjectPGODirectoryData &dataset, std::size_t robotId,
    std::size_t targetRobotId, const ManualObjectDranOptions &options,
    const SyntheticObjectMetadataSet *metadata) {
  Matrix costs(dataset.numObjects, dataset.numObjects);
  if (!metadata || !options.associationUseSyntheticMetadata) {
    for (std::size_t localObjectId = 0; localObjectId < dataset.numObjects;
         ++localObjectId) {
      for (std::size_t targetObjectId = 0;
           targetObjectId < dataset.numObjects; ++targetObjectId) {
        costs(static_cast<int>(localObjectId),
              static_cast<int>(targetObjectId)) =
            localObjectId == targetObjectId ? 0.0 : 1.0;
      }
    }
    applyObservedAssociationMask(dataset, robotId, targetRobotId, options,
                                 costs);
    return costs;
  }

  for (std::size_t localObjectId = 0; localObjectId < dataset.numObjects;
       ++localObjectId) {
    for (std::size_t targetObjectId = 0; targetObjectId < dataset.numObjects;
         ++targetObjectId) {
      if (!hasSyntheticObservationMetadata(metadata, robotId, targetRobotId,
                                           localObjectId, targetObjectId,
                                           options)) {
        costs(static_cast<int>(localObjectId),
              static_cast<int>(targetObjectId)) =
            localObjectId == targetObjectId ? 0.0 : 1.0;
        continue;
      }
      const SyntheticObjectObservationMetadata &local =
          metadata->observations[robotId][localObjectId];
      const SyntheticObjectObservationMetadata &target =
          metadata->observations[targetRobotId][targetObjectId];
      costs(static_cast<int>(localObjectId),
            static_cast<int>(targetObjectId)) =
          local.category == target.category ? 0.0 : 1.0;
    }
  }
  applyObservedAssociationMask(dataset, robotId, targetRobotId, options,
                               costs);
  return costs;
}

Matrix metadataAssociationCostMatrix(
    const ObjectPGODirectoryData &dataset, std::size_t robotId,
    std::size_t targetRobotId, const ManualObjectDranOptions &options,
    const SyntheticObjectMetadataSet *metadata) {
  if (!metadata || !options.associationUseSyntheticMetadata) {
    return classOnlyAssociationCostMatrix(dataset, robotId, targetRobotId,
                                          options, metadata);
  }
  Matrix costs = options.associationRequireObservedObjects
                     ? Matrix::Constant(
                           dataset.numObjects, dataset.numObjects,
                           std::numeric_limits<double>::infinity())
                     : Matrix(dataset.numObjects, dataset.numObjects);
  const std::vector<bool> localObserved =
      options.associationRequireObservedObjects
          ? observedObjects(dataset.robots[robotId], dataset.numObjects)
          : std::vector<bool>();
  const std::vector<bool> targetObserved =
      options.associationRequireObservedObjects
          ? observedObjects(dataset.robots[targetRobotId], dataset.numObjects)
          : std::vector<bool>();
  for (std::size_t localObjectId = 0; localObjectId < dataset.numObjects;
       ++localObjectId) {
    if (options.associationRequireObservedObjects &&
        !localObserved[localObjectId]) {
      continue;
    }
    for (std::size_t targetObjectId = 0; targetObjectId < dataset.numObjects;
         ++targetObjectId) {
      if (options.associationRequireObservedObjects &&
          !targetObserved[targetObjectId]) {
        continue;
      }
      costs(static_cast<int>(localObjectId),
            static_cast<int>(targetObjectId)) =
         syntheticMetadataAssociationCost(metadata, robotId, targetRobotId,
                                           localObjectId, targetObjectId,
                                           options);
    }
  }
  return costs;
}

struct AssociationCandidateSupport {
  int rows{0};
  int cols{0};
  std::vector<ManualObjectDranAssociationCandidateEdge> edges;
  std::vector<std::vector<std::size_t>> rowEdges;
  std::vector<std::vector<std::size_t>> colEdges;

  bool matches(const Matrix &matrix) const {
    return rows == matrix.rows() && cols == matrix.cols();
  }
};

std::vector<ManualObjectDranAssociationEntry>
activeAssociationEntriesOnCandidateSupport(
    const Matrix &weights, const AssociationCandidateSupport *support,
    double minWeight) {
  if (support == nullptr || !support->matches(weights)) {
    return activeAssociationEntries(weights, minWeight);
  }
  const double threshold =
      std::isfinite(minWeight) ? std::max(0.0, minWeight) : 0.0;
  std::vector<ManualObjectDranAssociationEntry> entries;
  entries.reserve(support->edges.size());
  for (const ManualObjectDranAssociationCandidateEdge &edge :
       support->edges) {
    if (edge.row >= static_cast<std::size_t>(weights.rows()) ||
        edge.col >= static_cast<std::size_t>(weights.cols())) {
      continue;
    }
    const double weight = weights(static_cast<int>(edge.row),
                                  static_cast<int>(edge.col));
    if (!std::isfinite(weight) || weight <= threshold) {
      continue;
    }
    entries.push_back(
        ManualObjectDranAssociationEntry{edge.row, edge.col, weight});
  }
  return entries;
}

