  std::size_t retryAttempts{0};
  std::size_t payloadBytes{0};
  std::size_t certificatePayloadBytes{0};
  double primalResidual{0.0};
  double dualResidual{0.0};
  double normalizedPrimalResidual{0.0};
  double normalizedDualResidual{0.0};
  std::size_t adaptiveBetaEdges{0};
  double adaptiveBetaSum{0.0};
