  double adaptiveMidpointResidual{0.0};
  double globalSpectralStep{0.0};
  std::size_t globalSpectralContributions{0};
  double globalSpectralNumerator{0.0};
  double globalSpectralDenominator{0.0};
  std::size_t edgeInertiaAttempts{0};
  std::size_t edgeInertiaAccepts{0};
  std::size_t edgeInertiaRestarts{0};
