std::vector<std::vector<Matrix>>
manualObjectDranPairExcludedAssociationWeightsForTest(
    const std::vector<std::vector<Matrix>> &weights,
    std::size_t firstRobot, std::size_t secondRobot) {
  if (firstRobot == secondRobot || firstRobot >= weights.size() ||
      secondRobot >= weights.size() ||
      secondRobot >= weights[firstRobot].size() ||
      firstRobot >= weights[secondRobot].size()) {
    throw std::invalid_argument(
        "pair-cavity excluded robot pair is invalid");
  }
  std::vector<std::vector<Matrix>> excluded = weights;
  excluded[firstRobot][secondRobot].setZero();
  excluded[secondRobot][firstRobot].setZero();
  return excluded;
}

Matrix manualObjectDranConditionalTranslationMeanForTest(
    const SparseMatrix &quadratic, const SparseMatrix &linear,
    const Matrix &state, unsigned dimension,
    const std::vector<std::size_t> &anchoredColumns) {
  if (quadratic.rows() != quadratic.cols() ||
      linear.rows() != state.rows() ||
      linear.cols() != quadratic.cols() ||
      state.cols() != quadratic.cols() || dimension == 0u ||
      quadratic.cols() % static_cast<int>(dimension + 1u) != 0) {
    throw std::invalid_argument(
        "pair-cavity conditional mean has incompatible dimensions");
  }
  const std::size_t totalColumns =
      static_cast<std::size_t>(quadratic.cols());
  std::vector<unsigned char> anchored(totalColumns, 0u);
  for (const std::size_t column : anchoredColumns) {
    if (column >= totalColumns) {
      throw std::invalid_argument(
          "pair-cavity conditional mean anchor is out of range");
    }
    anchored[column] = 1u;
  }
  std::vector<int> fullToFree(totalColumns, -1);
  std::vector<std::size_t> freeTranslations;
  const std::size_t numPoses = totalColumns / (dimension + 1u);
  for (std::size_t pose = 0; pose < numPoses; ++pose) {
    const std::size_t column = pose * (dimension + 1u) + dimension;
    if (anchored[column] == 0u) {
      fullToFree[column] = static_cast<int>(freeTranslations.size());
      freeTranslations.push_back(column);
    }
  }
  if (freeTranslations.empty()) {
    return state;
  }

  std::vector<Eigen::Triplet<double>> triplets;
  for (int outer = 0; outer < quadratic.outerSize(); ++outer) {
    for (SparseMatrix::InnerIterator entry(quadratic, outer); entry;
         ++entry) {
      const int row = fullToFree[static_cast<std::size_t>(entry.row())];
      const int col = fullToFree[static_cast<std::size_t>(entry.col())];
      if (row >= 0 && col >= 0) {
        triplets.emplace_back(row, col, entry.value());
      }
    }
  }
  Eigen::SparseMatrix<double, Eigen::ColMajor> translationQuadratic(
      static_cast<int>(freeTranslations.size()),
      static_cast<int>(freeTranslations.size()));
  translationQuadratic.setFromTriplets(triplets.begin(), triplets.end());
  translationQuadratic.makeCompressed();
  Eigen::SimplicialLDLT<Eigen::SparseMatrix<double, Eigen::ColMajor>> factor(
      translationQuadratic);
  if (factor.info() != Eigen::Success) {
    throw std::runtime_error(
        "pair-cavity conditional mean factorization failed");
  }
  const Vector diagonal = factor.vectorD();
  const double diagonalScale =
      diagonal.size() > 0 ? diagonal.cwiseAbs().maxCoeff() : 0.0;
  const double threshold = std::numeric_limits<double>::epsilon() *
                           static_cast<double>(translationQuadratic.rows()) *
                           std::max(1.0, diagonalScale);
  if (diagonal.size() != translationQuadratic.rows() ||
      (diagonal.array() <= threshold).any()) {
    throw std::runtime_error(
        "pair-cavity conditional translation system is not SPD");
  }

  Matrix gradient = state * quadratic;
  gradient += Matrix(linear);
  Matrix rhs(freeTranslations.size(), state.rows());
  for (std::size_t index = 0; index < freeTranslations.size(); ++index) {
    rhs.row(static_cast<int>(index)) =
        -gradient.col(static_cast<int>(freeTranslations[index])).transpose();
  }
  const Matrix response = factor.solve(rhs);
  if (factor.info() != Eigen::Success || !response.allFinite()) {
    throw std::runtime_error("pair-cavity conditional mean solve failed");
  }
  const double residual = (translationQuadratic * response - rhs).norm();
  const double residualTolerance =
      100.0 * std::numeric_limits<double>::epsilon() *
      std::max(1.0, translationQuadratic.norm()) *
      std::max(1.0, response.norm());
  if (!std::isfinite(residual) || residual > residualTolerance) {
    throw std::runtime_error(
        "pair-cavity conditional mean residual is too large");
  }
  Matrix recovered = state;
  for (std::size_t index = 0; index < freeTranslations.size(); ++index) {
    recovered.col(static_cast<int>(freeTranslations[index])) +=
        response.row(static_cast<int>(index)).transpose();
  }
  return recovered;
}

Matrix manualObjectDranSelectedCovarianceForTest(
    const SparseMatrix &quadratic,
    const std::vector<std::size_t> &anchoredColumns,
    const std::vector<std::size_t> &selectedColumns) {
  if (quadratic.rows() != quadratic.cols()) {
    throw std::invalid_argument("pair-cavity quadratic must be square");
  }
  const std::size_t dimension = static_cast<std::size_t>(quadratic.rows());
  std::vector<unsigned char> anchored(dimension, 0u);
  for (const std::size_t column : anchoredColumns) {
    if (column >= dimension) {
      throw std::invalid_argument(
          "pair-cavity anchored column is out of range");
    }
    anchored[column] = 1u;
  }
  std::vector<int> fullToFree(dimension, -1);
  std::vector<std::size_t> freeToFull;
  freeToFull.reserve(dimension);
  for (std::size_t column = 0; column < dimension; ++column) {
    if (anchored[column] == 0u) {
      fullToFree[column] = static_cast<int>(freeToFull.size());
      freeToFull.push_back(column);
    }
  }
  if (freeToFull.empty()) {
    throw std::runtime_error("pair-cavity quadratic has no free columns");
  }
  std::vector<Eigen::Triplet<double>> triplets;
  triplets.reserve(static_cast<std::size_t>(quadratic.nonZeros()));
  for (int outer = 0; outer < quadratic.outerSize(); ++outer) {
    for (SparseMatrix::InnerIterator entry(quadratic, outer); entry;
         ++entry) {
      const int row = fullToFree[static_cast<std::size_t>(entry.row())];
      const int col = fullToFree[static_cast<std::size_t>(entry.col())];
      if (row >= 0 && col >= 0) {
        triplets.emplace_back(row, col, entry.value());
      }
    }
  }
  Eigen::SparseMatrix<double, Eigen::ColMajor> freeQuadratic(
      static_cast<int>(freeToFull.size()),
      static_cast<int>(freeToFull.size()));
  freeQuadratic.setFromTriplets(triplets.begin(), triplets.end());
  freeQuadratic.makeCompressed();
  Eigen::SimplicialLDLT<Eigen::SparseMatrix<double, Eigen::ColMajor>> factor(
      freeQuadratic);
  if (factor.info() != Eigen::Success) {
    throw std::runtime_error("pair-cavity covariance factorization failed");
  }
  const Vector diagonal = factor.vectorD();
  const double diagonalScale =
      diagonal.size() > 0 ? diagonal.cwiseAbs().maxCoeff() : 0.0;
  const double threshold = std::numeric_limits<double>::epsilon() *
                           static_cast<double>(freeQuadratic.rows()) *
                           std::max(1.0, diagonalScale);
  if (diagonal.size() != freeQuadratic.rows() ||
      (diagonal.array() <= threshold).any()) {
    throw std::runtime_error(
        "pair-cavity quadratic is singular after gauge anchoring");
  }
  Matrix rhs = Matrix::Zero(freeQuadratic.rows(),
                            static_cast<int>(selectedColumns.size()));
  for (std::size_t index = 0; index < selectedColumns.size(); ++index) {
    const std::size_t column = selectedColumns[index];
    if (column >= dimension) {
      throw std::invalid_argument(
          "pair-cavity selected column is out of range");
    }
    const int freeColumn = fullToFree[column];
    if (freeColumn < 0) {
      throw std::invalid_argument(
          "pair-cavity selected column is anchored");
    }
    rhs(freeColumn, static_cast<int>(index)) = 1.0;
  }
  const Matrix solution = factor.solve(rhs);
  if (factor.info() != Eigen::Success || !solution.allFinite()) {
    throw std::runtime_error("pair-cavity covariance solve failed");
  }
  const double residual = (freeQuadratic * solution - rhs).norm();
  const double residualTolerance =
      100.0 * std::numeric_limits<double>::epsilon() *
      std::max(1.0, freeQuadratic.norm()) * std::max(1.0, solution.norm());
  if (!std::isfinite(residual) || residual > residualTolerance) {
    throw std::runtime_error(
        "pair-cavity covariance solve residual is too large");
  }
  Matrix covariance(selectedColumns.size(), selectedColumns.size());
  for (std::size_t row = 0; row < selectedColumns.size(); ++row) {
    const int freeRow = fullToFree[selectedColumns[row]];
    covariance.row(static_cast<int>(row)) = solution.row(freeRow);
  }
  return 0.5 * (covariance + covariance.transpose());
}

std::size_t
manualObjectDranProjectCompletePoint2ConsensusForTest(
    const std::vector<std::size_t> &objectOffsets, std::size_t numObjects,
    unsigned dimension, double relaxation, std::vector<Matrix> &states,
    std::vector<std::vector<Matrix>> &neighborStateCache) {
  if (dimension < 2u || states.empty() || objectOffsets.size() != states.size() ||
      neighborStateCache.size() != states.size() ||
      !std::isfinite(relaxation) || relaxation <= 0.0 || relaxation > 1.0) {
    throw std::invalid_argument(
        "complete Point2 projection has incompatible dimensions");
  }
  const std::size_t blockWidth = dimension + 1u;
  auto validateState = [&](const Matrix &state, std::size_t sender) {
    const std::size_t requiredBlocks = objectOffsets.at(sender) + numObjects;
    if (state.rows() != static_cast<Eigen::Index>(dimension) ||
        state.cols() < static_cast<Eigen::Index>(requiredBlocks * blockWidth) ||
        !state.allFinite()) {
      throw std::invalid_argument(
          "complete Point2 projection state is not block aligned");
    }
  };
  for (std::size_t robot = 0; robot < states.size(); ++robot) {
    validateState(states[robot], robot);
    if (neighborStateCache[robot].size() != states.size()) {
      throw std::invalid_argument(
          "complete Point2 projection cache is not complete");
    }
  }

  std::vector<std::vector<Vector>> means(
      states.size(), std::vector<Vector>(numObjects, Vector::Zero(2)));
  for (std::size_t receiver = 0; receiver < states.size(); ++receiver) {
    for (std::size_t object = 0; object < numObjects; ++object) {
      const std::size_t ownCol =
          (objectOffsets[receiver] + object) * blockWidth + dimension;
      means[receiver][object] = states[receiver].col(ownCol).head(2);
      for (std::size_t sender = 0; sender < states.size(); ++sender) {
        if (sender == receiver) {
          continue;
        }
        validateState(neighborStateCache[receiver][sender], sender);
        const std::size_t senderCol =
            (objectOffsets[sender] + object) * blockWidth + dimension;
        means[receiver][object] +=
            neighborStateCache[receiver][sender].col(senderCol).head(2);
      }
      means[receiver][object] /= static_cast<double>(states.size());
    }
  }

  for (std::size_t receiver = 0; receiver < states.size(); ++receiver) {
    for (std::size_t object = 0; object < numObjects; ++object) {
      const std::size_t ownCol =
          (objectOffsets[receiver] + object) * blockWidth + dimension;
      states[receiver].col(ownCol).head(2) +=
          relaxation *
          (means[receiver][object] - states[receiver].col(ownCol).head(2));
      for (std::size_t sender = 0; sender < states.size(); ++sender) {
        if (neighborStateCache[receiver][sender].size() == 0) {
          continue;
        }
        const std::size_t senderCol =
            (objectOffsets[sender] + object) * blockWidth + dimension;
        neighborStateCache[receiver][sender].col(senderCol).head(2) +=
            relaxation *
            (means[receiver][object] -
             neighborStateCache[receiver][sender].col(senderCol).head(2));
      }
    }
  }
  return states.size() * numObjects;
}

std::vector<std::vector<Matrix>>
manualObjectDranCompleteObjectPoseMeansForTest(
    const std::vector<std::size_t> &objectOffsets, std::size_t numObjects,
    unsigned dimension, const std::vector<Matrix> &states,
    const std::vector<std::vector<Matrix>> &neighborStateCache) {
  if ((dimension != 2u && dimension != 3u) || states.empty() ||
      objectOffsets.size() != states.size() ||
      neighborStateCache.size() != states.size()) {
    throw std::invalid_argument(
        "complete ObjectPose mean has incompatible dimensions");
  }
  const std::size_t blockWidth = dimension + 1u;
  const auto validateState = [&](const Matrix &state, std::size_t sender) {
    const std::size_t requiredBlocks = objectOffsets.at(sender) + numObjects;
    if (state.rows() != static_cast<Eigen::Index>(dimension) ||
        state.cols() <
            static_cast<Eigen::Index>(requiredBlocks * blockWidth) ||
        !state.allFinite()) {
      throw std::invalid_argument(
          "complete ObjectPose mean state is not block aligned");
    }
  };
  for (std::size_t receiver = 0; receiver < states.size(); ++receiver) {
    validateState(states[receiver], receiver);
    if (neighborStateCache[receiver].size() != states.size()) {
      throw std::invalid_argument(
          "complete ObjectPose mean cache is not complete");
    }
  }

  std::vector<std::vector<Matrix>> means(
      states.size(),
      std::vector<Matrix>(numObjects,
                          Matrix::Zero(dimension, dimension + 1u)));
  for (std::size_t receiver = 0; receiver < states.size(); ++receiver) {
    for (std::size_t object = 0; object < numObjects; ++object) {
      Matrix sum = Matrix::Zero(dimension, dimension + 1u);
      for (std::size_t sender = 0; sender < states.size(); ++sender) {
        const Matrix &source =
            sender == receiver ? states[receiver]
                               : neighborStateCache[receiver][sender];
        validateState(source, sender);
        sum += blockPose(source, objectOffsets[sender] + object, dimension);
      }
      sum /= static_cast<double>(states.size());
      sum.leftCols(dimension) =
          projectToRotationGroup(sum.leftCols(dimension));
      means[receiver][object] = std::move(sum);
    }
  }
  return means;
}

Matrix manualObjectDranCompleteObjectPoseGaugeForTest(
    const Matrix &state, std::size_t objectOffset,
    const std::vector<Matrix> &objectMeans, unsigned dimension) {
  const std::size_t blockWidth = dimension + 1u;
  const std::size_t requiredBlocks = objectOffset + objectMeans.size();
  if ((dimension != 2u && dimension != 3u) || objectMeans.empty() ||
      state.rows() != static_cast<Eigen::Index>(dimension) ||
      state.cols() <
          static_cast<Eigen::Index>(requiredBlocks * blockWidth) ||
      !state.allFinite()) {
    throw std::invalid_argument(
        "complete ObjectPose gauge has incompatible dimensions");
  }

  Matrix rotationSum = Matrix::Zero(dimension, dimension);
  for (std::size_t object = 0; object < objectMeans.size(); ++object) {
    if (objectMeans[object].rows() !=
            static_cast<Eigen::Index>(dimension) ||
        objectMeans[object].cols() !=
            static_cast<Eigen::Index>(blockWidth) ||
        !objectMeans[object].allFinite()) {
      throw std::invalid_argument(
          "complete ObjectPose gauge target is invalid");
    }
    const Matrix source =
        blockPose(state, objectOffset + object, dimension);
    rotationSum.noalias() +=
        objectMeans[object].leftCols(dimension) *
        source.leftCols(dimension).transpose();
  }
  const Matrix rotation = projectToRotationGroup(rotationSum);
  Vector translation = Vector::Zero(dimension);
  for (std::size_t object = 0; object < objectMeans.size(); ++object) {
    const Matrix source =
        blockPose(state, objectOffset + object, dimension);
    translation.noalias() += objectMeans[object].rightCols(1) -
                             rotation * source.rightCols(1);
  }
  translation /= static_cast<double>(objectMeans.size());
  Matrix gauge = Matrix::Zero(dimension, blockWidth);
  gauge.leftCols(dimension) = rotation;
  gauge.col(dimension) = translation;
  return gauge;
}

bool manualObjectDranPoint2ConsensusProjectionActiveForTest(
    bool enabled, std::size_t projectionRounds, unsigned iteration) {
  return enabled && iteration > 0u &&
         (projectionRounds == 0u || iteration <= projectionRounds);
}

bool manualObjectDranPoint2ConsensusShouldResetDualForTest(
    bool enabled, std::size_t projectionRounds, unsigned iteration) {
  return enabled && projectionRounds > 0u && iteration == projectionRounds;
}

bool manualObjectDranDirectEdgeDualRelaxationCanSettleForTest(
    bool projectionEnabled, std::size_t projectionRounds,
    std::size_t refreshRound) {
  if (!projectionEnabled) {
    return true;
  }
  return projectionRounds > 0u && refreshRound > projectionRounds;
}

bool manualObjectDranShouldPruneInactiveDirectEdgeDualForTest(
    bool preserveInactiveDuals, bool active) {
  return !active && !preserveInactiveDuals;
}

bool manualObjectDranShouldPruneInactiveDirectEdgeTargetForTest(
    bool fixedUnionModel, bool active) {
  return !active && !fixedUnionModel;
}

ManualObjectDranTranslationSchurModel
manualObjectDranTranslationQuadraticForTest(
    const std::vector<RelativeSEMeasurement> &measurements,
    const Matrix &state, std::size_t numPoses, unsigned d) {
  if (d == 0u || numPoses == 0u ||
      state.cols() != static_cast<Eigen::Index>(numPoses * (d + 1u)) ||
      state.rows() != static_cast<Eigen::Index>(d) || !state.allFinite()) {
    throw std::invalid_argument(
        "component translation quadratic has incompatible state dimensions");
  }
  ManualObjectDranTranslationSchurModel result;
  result.hessian = Matrix::Zero(numPoses, numPoses);
  result.gradient = Matrix::Zero(numPoses, d);
  for (const RelativeSEMeasurement &measurement : measurements) {
    if (measurement.p1 >= numPoses || measurement.p2 >= numPoses ||
        measurement.t.size() != static_cast<Eigen::Index>(d)) {
      throw std::invalid_argument(
          "component translation quadratic measurement is out of range");
    }
    const Matrix firstPose = blockPose(state, measurement.p1, d);
    const Matrix secondPose = blockPose(state, measurement.p2, d);
    const Eigen::RowVectorXd residual =
        (secondPose.rightCols(1) - firstPose.rightCols(1) -
         firstPose.leftCols(d) * measurement.t)
            .transpose();
    const double scale = 2.0 * measurement.weight * measurement.tau;
    if (!std::isfinite(scale) || scale < 0.0) {
      throw std::invalid_argument(
          "component translation quadratic information is invalid");
    }
    const Eigen::Index first =
        static_cast<Eigen::Index>(measurement.p1);
    const Eigen::Index second =
        static_cast<Eigen::Index>(measurement.p2);
    result.hessian(first, first) += scale;
    result.hessian(second, second) += scale;
    result.hessian(first, second) -= scale;
    result.hessian(second, first) -= scale;
    result.gradient.row(first).noalias() -= scale * residual;
    result.gradient.row(second).noalias() += scale * residual;
  }
  result.valid = true;
  return result;
}

ManualObjectDranTranslationSchurModel
manualObjectDranTranslationSchurForTest(
    const Matrix &hessian, const Matrix &gradient,
    const std::vector<std::size_t> &boundary) {
  if (hessian.rows() == 0 || hessian.rows() != hessian.cols() ||
      gradient.rows() != hessian.rows() || !hessian.allFinite() ||
      !gradient.allFinite() || boundary.empty()) {
    throw std::invalid_argument(
        "component translation Schur model has incompatible input");
  }
  std::vector<unsigned char> isBoundary(
      static_cast<std::size_t>(hessian.rows()), 0u);
  for (const std::size_t index : boundary) {
    if (index >= isBoundary.size() || isBoundary[index] != 0u) {
      throw std::invalid_argument(
          "component translation Schur boundary is invalid");
    }
    isBoundary[index] = 1u;
  }
  std::vector<std::size_t> privateIndices;
  for (std::size_t index = 0; index < isBoundary.size(); ++index) {
    if (isBoundary[index] == 0u) {
      privateIndices.push_back(index);
    }
  }
  const auto select = [](const Matrix &matrix,
                         const std::vector<std::size_t> &rows,
                         const std::vector<std::size_t> &cols) {
    Matrix selected(rows.size(), cols.size());
    for (std::size_t row = 0; row < rows.size(); ++row) {
      for (std::size_t col = 0; col < cols.size(); ++col) {
        selected(static_cast<Eigen::Index>(row),
                 static_cast<Eigen::Index>(col)) =
            matrix(static_cast<Eigen::Index>(rows[row]),
                   static_cast<Eigen::Index>(cols[col]));
      }
    }
    return selected;
  };
  const auto selectRows = [](const Matrix &matrix,
                             const std::vector<std::size_t> &rows) {
    Matrix selected(rows.size(), matrix.cols());
    for (std::size_t row = 0; row < rows.size(); ++row) {
      selected.row(static_cast<Eigen::Index>(row)) =
          matrix.row(static_cast<Eigen::Index>(rows[row]));
    }
    return selected;
  };
  ManualObjectDranTranslationSchurModel result;
  result.hessian = select(hessian, boundary, boundary);
  result.gradient = selectRows(gradient, boundary);
  if (!privateIndices.empty()) {
    const Matrix privateHessian =
        select(hessian, privateIndices, privateIndices);
    const Matrix privateBoundary =
        select(hessian, privateIndices, boundary);
    const Matrix privateGradient = selectRows(gradient, privateIndices);
    Eigen::LDLT<Matrix> factor(privateHessian);
    if (factor.info() != Eigen::Success) {
      throw std::runtime_error(
          "component translation private factorization failed");
    }
    const Vector diagonal = factor.vectorD();
    const double scale =
        diagonal.size() > 0 ? diagonal.cwiseAbs().maxCoeff() : 0.0;
    const double threshold =
        std::numeric_limits<double>::epsilon() *
        static_cast<double>(std::max<Eigen::Index>(1, diagonal.size())) *
        std::max(1.0, scale);
    if ((diagonal.array() <= threshold).any()) {
      throw std::runtime_error(
          "component translation private Hessian is not SPD");
    }
    const Matrix solvedBoundary = factor.solve(privateBoundary);
    const Matrix solvedGradient = factor.solve(privateGradient);
    if (factor.info() != Eigen::Success || !solvedBoundary.allFinite() ||
        !solvedGradient.allFinite()) {
      throw std::runtime_error(
          "component translation private solve failed");
    }
    result.hessian.noalias() -=
        privateBoundary.transpose() * solvedBoundary;
    result.gradient.noalias() -=
        privateBoundary.transpose() * solvedGradient;
  }
  result.hessian = 0.5 * (result.hessian + result.hessian.transpose());
  result.valid = true;
  return result;
}

ManualObjectDranTranslationResponse
manualObjectDranTranslationResponseForTest(
    const Matrix &physicalHessian, const Matrix &physicalGradient,
    const Matrix &positions,
    const std::vector<ManualObjectDranTranslationAssociationEdge>
        &currentEdges,
    const std::vector<ManualObjectDranTranslationAssociationEdge>
        &candidateEdges) {
  const Eigen::Index count = physicalHessian.rows();
  if (count == 0 || physicalHessian.cols() != count ||
      physicalGradient.rows() != count || positions.rows() != count ||
      physicalGradient.cols() != positions.cols() ||
      !physicalHessian.allFinite() || !physicalGradient.allFinite() ||
      !positions.allFinite()) {
    throw std::invalid_argument(
        "component translation response has incompatible input dimensions");
  }
  struct SolveResult {
    Matrix step;
    double residual{0.0};
    double energyErrorBound{0.0};
    std::size_t nullity{0};
  };
  const auto responseForEdges =
      [&](const std::vector<ManualObjectDranTranslationAssociationEdge>
              &edges) {
        Matrix hessian = 0.5 * (physicalHessian + physicalHessian.transpose());
        Matrix gradient = physicalGradient;
        for (const ManualObjectDranTranslationAssociationEdge &edge : edges) {
          if (edge.first >= static_cast<std::size_t>(count) ||
              edge.second >= static_cast<std::size_t>(count) ||
              edge.first == edge.second || !std::isfinite(edge.information) ||
              edge.information < 0.0) {
            throw std::invalid_argument(
                "component translation response has an invalid edge");
          }
          if (edge.information == 0.0) {
            continue;
          }
          const Eigen::Index first = static_cast<Eigen::Index>(edge.first);
          const Eigen::Index second = static_cast<Eigen::Index>(edge.second);
          const double weight = edge.information;
          const Eigen::RowVectorXd residual =
              positions.row(first) - positions.row(second);
          hessian(first, first) += weight;
          hessian(second, second) += weight;
          hessian(first, second) -= weight;
          hessian(second, first) -= weight;
          gradient.row(first).noalias() += weight * residual;
          gradient.row(second).noalias() -= weight * residual;
        }
        hessian = 0.5 * (hessian + hessian.transpose());
        Eigen::SelfAdjointEigenSolver<Matrix> eigensolver(hessian);
        if (eigensolver.info() != Eigen::Success) {
          throw std::runtime_error(
              "component translation response eigensolve failed");
        }
        const Vector eigenvalues = eigensolver.eigenvalues();
        const Matrix eigenvectors = eigensolver.eigenvectors();
        const double scale =
            std::max(1.0, eigenvalues.cwiseAbs().maxCoeff());
        const double threshold =
            8.0 * std::numeric_limits<double>::epsilon() *
            static_cast<double>(std::max<Eigen::Index>(1, count)) * scale;
        if (eigenvalues.minCoeff() < -threshold) {
          throw std::runtime_error(
              "component translation response Hessian is not PSD");
        }
        SolveResult result;
        result.step = Matrix::Zero(count, gradient.cols());
        double minimumPositive = std::numeric_limits<double>::infinity();
        for (Eigen::Index index = 0; index < count; ++index) {
          const double eigenvalue = eigenvalues(index);
          if (eigenvalue <= threshold) {
            ++result.nullity;
            continue;
          }
          minimumPositive = std::min(minimumPositive, eigenvalue);
          const Vector eigenvector = eigenvectors.col(index);
          result.step.noalias() -=
              eigenvector * (eigenvector.transpose() * gradient) / eigenvalue;
        }
        result.residual = (hessian * result.step + gradient).norm();
        if (std::isfinite(minimumPositive) && minimumPositive > 0.0) {
          result.energyErrorBound =
              result.residual * result.residual / (2.0 * minimumPositive);
        }
        return result;
      };
  const SolveResult current = responseForEdges(currentEdges);
  const SolveResult candidate = responseForEdges(candidateEdges);
  const auto physicalChange = [&](const Matrix &step) {
    return (physicalGradient.array() * step.array()).sum() +
           0.5 * (step.transpose() * physicalHessian * step).trace();
  };
  ManualObjectDranTranslationResponse result;
  result.valid = true;
  result.currentPhysicalChange = physicalChange(current.step);
  result.candidatePhysicalChange = physicalChange(candidate.step);
  result.predictedPhysicalDelta =
      result.candidatePhysicalChange - result.currentPhysicalChange;
  result.currentLinearResidual = current.residual;
  result.candidateLinearResidual = candidate.residual;
  result.currentNullity = current.nullity;
  result.candidateNullity = candidate.nullity;
  result.numericalErrorBound =
      current.energyErrorBound + candidate.energyErrorBound;
  return result;
}

std::vector<Matrix> manualObjectDranRobotGaugeTransformsForTest(
    const std::vector<std::vector<Matrix>> &edgeTransforms,
    bool asynchronousGaussSeidel) {
  ObjectPGODirectoryData dataset;
  dataset.numRobots = edgeTransforms.size();
  dataset.numObjects = 1;
  dataset.robots.resize(dataset.numRobots);
  NeighborRound neighbors(dataset.numRobots);
  DirectedAssociationTransforms transforms(
      dataset.numRobots,
      std::vector<AssociationTransform>(dataset.numRobots));
  DirectedAssociationWeights weights(
      dataset.numRobots, std::vector<Matrix>(dataset.numRobots));
  for (std::size_t receiver = 0; receiver < dataset.numRobots; ++receiver) {
    for (std::size_t sender = 0; sender < dataset.numRobots; ++sender) {
      if (receiver == sender || receiver >= edgeTransforms.size() ||
          sender >= edgeTransforms[receiver].size() ||
          edgeTransforms[receiver][sender].rows() != 3 ||
          edgeTransforms[receiver][sender].cols() != 4) {
        continue;
      }
      neighbors[receiver].push_back(
          {static_cast<unsigned>(sender), 1.0});
      transforms[receiver][sender].valid = true;
      transforms[receiver][sender].transform =
          edgeTransforms[receiver][sender];
      weights[receiver][sender] = Matrix::Ones(1, 1);
    }
  }
  const DirectedAssociationReliabilities reliabilities =
      makeUnitDirectedAssociationReliabilities(dataset.numRobots,
                                                dataset.numObjects);
  ManualObjectDranOptions testOptions;
  testOptions.associationGaugeSynchronizationAsynchronousGaussSeidel =
      asynchronousGaussSeidel;
  const std::vector<AssociationTransform> gauges =
      computeRobotGaugeTransformsFromAssociationTransforms(
          dataset, neighbors, testOptions, weights,
          reliabilities, 3, transforms);
  std::vector<Matrix> result;
  result.reserve(gauges.size());
  for (const AssociationTransform &gauge : gauges) {
    result.push_back(gauge.valid ? gauge.transform : Matrix());
  }
  return result;
}

std::vector<Matrix> manualObjectDranRobotGaugeTransformsWithRmseForTest(
    const std::vector<std::vector<Matrix>> &edgeTransforms,
    const std::vector<std::vector<double>> &edgeTranslationRmse) {
  ObjectPGODirectoryData dataset;
  dataset.numRobots = edgeTransforms.size();
  dataset.numObjects = 1;
  dataset.robots.resize(dataset.numRobots);
  NeighborRound neighbors(dataset.numRobots);
  DirectedAssociationTransforms transforms(
      dataset.numRobots,
      std::vector<AssociationTransform>(dataset.numRobots));
  DirectedAssociationWeights weights(
      dataset.numRobots, std::vector<Matrix>(dataset.numRobots));
  for (std::size_t receiver = 0; receiver < dataset.numRobots; ++receiver) {
    for (std::size_t sender = 0; sender < dataset.numRobots; ++sender) {
      if (receiver == sender || receiver >= edgeTransforms.size() ||
          sender >= edgeTransforms[receiver].size() ||
          edgeTransforms[receiver][sender].rows() != 3 ||
          edgeTransforms[receiver][sender].cols() != 4) {
        continue;
      }
      neighbors[receiver].push_back(
          {static_cast<unsigned>(sender), 1.0});
      transforms[receiver][sender].valid = true;
      transforms[receiver][sender].transform =
          edgeTransforms[receiver][sender];
      if (receiver < edgeTranslationRmse.size() &&
          sender < edgeTranslationRmse[receiver].size()) {
        transforms[receiver][sender].translationRmse =
            edgeTranslationRmse[receiver][sender];
      }
      weights[receiver][sender] = Matrix::Ones(1, 1);
    }
  }
  const DirectedAssociationReliabilities reliabilities =
      makeUnitDirectedAssociationReliabilities(dataset.numRobots,
                                                dataset.numObjects);
  const std::vector<AssociationTransform> gauges =
      computeRobotGaugeTransformsFromAssociationTransforms(
          dataset, neighbors, ManualObjectDranOptions(), weights,
          reliabilities, 3, transforms);
  std::vector<Matrix> result;
  result.reserve(gauges.size());
  for (const AssociationTransform &gauge : gauges) {
    result.push_back(gauge.valid ? gauge.transform : Matrix());
  }
  return result;
}

double manualObjectDranDescriptorAssociationCostForTest(
    const Vector &first, const Vector &second, double weight) {
  SyntheticObjectMetadataSet metadata;
  metadata.observations.resize(2);
  for (std::size_t robotId = 0; robotId < 2; ++robotId) {
    SyntheticObjectObservationMetadata observation;
    observation.robotId = robotId;
    observation.objectId = 0;
    observation.category = 0;
    observation.semanticConfidence = 1.0;
    observation.shape = Vector::Ones(3);
    observation.descriptor = robotId == 0 ? first : second;
    metadata.observations[robotId].push_back(std::move(observation));
  }
  ManualObjectDranOptions options;
  options.associationUseSyntheticMetadata = true;
  options.associationSemanticWeight = 0.0;
  options.associationShapeWeight = 0.0;
  options.associationDescriptorWeight = weight;
  return syntheticMetadataAssociationCost(
      &metadata, 0, 1, 0, 0, options);
}

