        summaryOptions.coupledPoint2SchurOracleCorrection
            ? pendingExactPoint2Diagnostics.iterationPayloadBytes
            : 0u;
    summary.iterCommMb =
        static_cast<double>(exactPoint2Mode
                                ? pendingExactPoint2Diagnostics
                                      .iterationPayloadBytes
                                : endpointPayloadBytes +
                                      coupledSchurPayloadBytes) /
        (1024.0 * 1024.0);
    cumulativeCommPoseCount += summary.commPoseCount;
    cumulativeCommMb += summary.iterCommMb;
    cumulativeSharedEdgeAssociationMb += summary.associationSharedEdgePayloadMb;
    cumulativeSharedObjectConsensusMb +=
        summary.lowerSharedObjectConsensusPayloadMb;
    summary.cumulativeCommPoseCount = cumulativeCommPoseCount;
    summary.cumulativeCommMb = cumulativeCommMb;
    summary.integratedPoint2AmmAttempts =
        pendingIntegratedPoint2AmmAttempts;
    summary.integratedPoint2AmmAccepts =
        pendingIntegratedPoint2AmmAccepts;
    summary.integratedPoint2AmmRestarts =
        pendingIntegratedPoint2AmmRestarts;
    summary.integratedPoint2EdgeInertiaAttempts =
        pendingIntegratedPoint2EdgeInertiaAttempts;
    summary.integratedPoint2EdgeInertiaAccepts =
        pendingIntegratedPoint2EdgeInertiaAccepts;
    summary.integratedPoint2EdgeInertiaRestarts =
        pendingIntegratedPoint2EdgeInertiaRestarts;
    summary.integratedPoint2EdgeBaselineMerit =
        pendingIntegratedPoint2EdgeBaselineMerit;
    summary.integratedPoint2EdgeAcceleratedMerit =
        pendingIntegratedPoint2EdgeAcceleratedMerit;
    summary.integratedPoint2OwnerMomentumValidContributions =
        pendingIntegratedPoint2OwnerMomentumValidContributions;
    summary.integratedPoint2OwnerMomentumMean =
        pendingIntegratedPoint2OwnerMomentumCount > 0u
            ? pendingIntegratedPoint2OwnerMomentumSum /
                  static_cast<double>(
                      pendingIntegratedPoint2OwnerMomentumCount)
            : 0.0;
    summary.integratedPoint2OwnerMomentumMin =
        pendingIntegratedPoint2OwnerMomentumCount > 0u
            ? pendingIntegratedPoint2OwnerMomentumMin
            : 0.0;
    summary.integratedPoint2OwnerMomentumMax =
        pendingIntegratedPoint2OwnerMomentumCount > 0u
            ? pendingIntegratedPoint2OwnerMomentumMax
            : 0.0;
    summary.associationSharedEdgeCumulativeMb =
        cumulativeSharedEdgeAssociationMb;
    summary.associationSharedEdgeCumulativeTotalMb =
        summary.cumulativeCommMb + summary.associationSharedEdgeCumulativeMb +
        cumulativeSharedObjectConsensusMb;
    summary.lowerSharedObjectConsensusCumulativeMb =
        cumulativeSharedObjectConsensusMb;
    summary.cumulativeTotalCommMb =
        summary.associationSharedEdgeCumulativeTotalMb;
    summary.exactPoint2TrajectoryConditionalCostBefore =
        pendingExactPoint2Diagnostics.trajectoryConditionalCostBefore;
    summary.exactPoint2TrajectoryConditionalCostAfter =
        pendingExactPoint2Diagnostics.trajectoryConditionalCostAfter;
    summary.exactPoint2TrajectoryAcceptedSolves =
        pendingExactPoint2Diagnostics.trajectoryAcceptedSolves;
    summary.exactPoint2TrajectoryRejectedSolves =
        pendingExactPoint2Diagnostics.trajectoryRejectedSolves;
    summary.exactPoint2TrajectorySolverSeconds =
        pendingExactPoint2Diagnostics.trajectorySolverSeconds;
    summary.exactPoint2UpdateSeconds =
        pendingExactPoint2Diagnostics.updateSeconds;
    summary.exactPoint2StatisticMessages =
        pendingExactPoint2Diagnostics.statisticMessages;
    summary.exactPoint2StatisticPayloadBytes =
        pendingExactPoint2Diagnostics.statisticPayloadBytes;
    summary.exactPoint2BroadcastMessages =
        pendingExactPoint2Diagnostics.broadcastMessages;
    summary.exactPoint2BroadcastPayloadBytes =
        pendingExactPoint2Diagnostics.broadcastPayloadBytes;
