        pendingExactPoint2Diagnostics.iterationPayloadBytes;
    cumulativeExactPoint2PayloadBytes +=
        pendingExactPoint2Diagnostics.iterationPayloadBytes;
    summary.exactPoint2CumulativePayloadBytes =
        cumulativeExactPoint2PayloadBytes;
    summary.exactPoint2MaxCopySpread =
        pendingExactPoint2Diagnostics.maxCopySpread;
