    summary.exactPoint2PhysicalCostAfterUpdate =
        pendingExactPoint2Diagnostics.physicalCostAfterUpdate;
    summary.exactPoint2Status = pendingExactPoint2Diagnostics.status;
    summary.point2SchurOracleActive =
        pendingExactPoint2Diagnostics.schurOracleActive;
    summary.point2SchurOracleAssemblySeconds =
        pendingExactPoint2Diagnostics.schurOracleAssemblySeconds;
    summary.point2SchurOracleResponseSolves =
        pendingExactPoint2Diagnostics.schurOracleResponseSolves;
    summary.point2SchurOracleMaxResponseRelativeResidual =
        pendingExactPoint2Diagnostics
            .schurOracleMaxResponseRelativeResidual;
    summary.point2SchurOracleSymmetryError =
        pendingExactPoint2Diagnostics.schurOracleSymmetryError;
    summary.point2SchurOracleSpectralShift =
        pendingExactPoint2Diagnostics.schurOracleSpectralShift;
